function formatSpeed(value) {
  return `${formatBytes(value)}/s`;
}

function formatRatio(value) {
  return (Number(value) || 0).toFixed(2);
}

function formatPercent(value) {
  return `${(Math.max(0, Math.min(1, Number(value) || 0)) * 100).toFixed(1)} %`;
}

function formatEta(seconds) {
  const value = Number(seconds);
  if (!Number.isFinite(value) || value <= 0 || value >= 8640000) return "—";
  const hours = Math.floor(value / 3600);
  const minutes = Math.floor((value % 3600) / 60);
  if (hours >= 24) return `${Math.floor(hours / 24)} j ${hours % 24} h`;
  if (hours > 0) return `${hours} h ${minutes.toString().padStart(2, "0")}`;
  return `${Math.max(1, minutes)} min`;
}

function formatDate(timestamp) {
  const value = Number(timestamp);
  if (!Number.isFinite(value) || value <= 0) return "—";
  return new Date(value * 1000).toLocaleString("fr-FR", { dateStyle: "short", timeStyle: "short" });
}

function formatIsoDate(value) {
  if (!value) return "—";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return "—";
  return parsed.toLocaleString("fr-FR", { dateStyle: "short", timeStyle: "short" });
}

function formatDay(value) {
  if (!value) return "—";
  const parsed = new Date(`${value}T00:00:00`);
  if (Number.isNaN(parsed.getTime())) return value;
  return parsed.toLocaleDateString("fr-FR", { dateStyle: "medium" });
}

function formatRelativeTime(value) {
  if (!value) return "A l'instant";
  const parsed = new Date(value);
  if (Number.isNaN(parsed.getTime())) return "Date inconnue";
  const diffSeconds = Math.max(0, Math.round((Date.now() - parsed.getTime()) / 1000));
  if (diffSeconds < 45) return "A l'instant";
  if (diffSeconds < 3600) return `Il y a ${Math.max(1, Math.round(diffSeconds / 60))} min`;
  if (diffSeconds < 86400) {
    const hours = Math.round(diffSeconds / 3600);
    return `Il y a ${hours} h`;
  }
  return `Il y a ${Math.round(diffSeconds / 86400)} j`;
}

function normalizeTags(tags) {
  return String(tags || "")
    .split(",")
    .map((tag) => tag.trim())
    .filter(Boolean);
}

function stateMeta(torrent) {
  const raw = String(torrent.state || "unknown");
  const meta = STATE_META[raw] || STATE_META.unknown;
  if (meta.group === "paused" && Number(torrent.progress) >= 1) {
    return { ...meta, group: "paused", text: meta.text };
  }
  if (!STATE_META[raw] && Number(torrent.progress) >= 1) {
    return { group: "complete", text: "Terminé", icon: "✓" };
  }
  return meta;
}

const COMPLETE_TORRENT_STATES = new Set([
  "uploading",
  "stalledUP",
  "forcedUP",
  "queuedUP",
  "checkingUP",
  "pausedUP",
  "stoppedUP",
]);

function isComplete(torrent) {
  const progress = Number(torrent.progress) || 0;
  return progress >= 1 || (COMPLETE_TORRENT_STATES.has(String(torrent.state || "")) && progress >= 0.999);
}

function clearError() {
  els.alert.hidden = true;
  els.alertText.textContent = "";
}

const showToast = createToast(() => els.toast);

function showUndoToast(message, actionLabel, onUndo, duration = 6000) {
  const el = els.toast;
  if (!el) return;
  el.replaceChildren(document.createTextNode(message));
  const undo = document.createElement("button");
  undo.type = "button";
  undo.className = "toast-action";
  undo.textContent = actionLabel;
  undo.addEventListener("click", () => {
    clearTimeout(state.undoToastTimer);
    el.hidden = true;
    onUndo?.();
  });
  el.append(undo);
  el.hidden = false;
  clearTimeout(state.undoToastTimer);
  state.undoToastTimer = window.setTimeout(() => { el.hidden = true; }, duration);
}

function formatFreshness(date) {
  if (!date) return "";
  const s = Math.max(0, Math.round((Date.now() - date.getTime()) / 1000));
  if (s < 10) return "à l'instant";
  if (s < 60) return `il y a ${s} s`;
  const m = Math.round(s / 60);
  if (m < 60) return `il y a ${m} min`;
  return date.toLocaleString("fr-FR", { dateStyle: "short", timeStyle: "short" });
}
const showError = (error) => showErrorMessage(els.alert, error, { messageElement: els.alertText });

function route(path = "/") {
  if (path === "/") return `${state.publicPrefix || ""}/`;
  return `${state.publicPrefix}${path.startsWith("/") ? path : `/${path}`}`;
}

const torrentApiClient = createApiClient({
  csrfHeader: "X-Torrent-Panel-CSRF",
  getCsrfToken: () => state.csrfToken,
  setCsrfToken: (token) => { state.csrfToken = token; },
  sessionPath: route("/api/session"),
});
const api = torrentApiClient.request;
const refreshSession = torrentApiClient.refreshSession;

function currentUrl() {
  const href = window.location?.href || `http://localhost${route("/")}`;
  if (typeof URL !== "undefined") return new URL(href);
  const raw = String(href);
  const query = raw.includes("?") ? raw.slice(raw.indexOf("?") + 1) : "";
  const params = new Map(
    query
      .split("&")
      .filter(Boolean)
      .map((entry) => {
        const [key, value = ""] = entry.split("=");
        return [decodeURIComponent(key), decodeURIComponent(value)];
      }),
  );
  return {
    searchParams: {
      get(key) {
        return params.has(key) ? params.get(key) : null;
      },
      set(key, value) {
        params.set(key, String(value));
      },
      delete(key) {
        params.delete(key);
      },
    },
    toString() {
      const base = raw.split("?")[0];
      const search = [...params.entries()].map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`).join("&");
      return search ? `${base}?${search}` : base;
    },
  };
}

function updateUrl(replace = true) {
  const url = currentUrl();
  url.searchParams.set("view", state.activeView);
  if (state.activeView === "torrents") {
    for (const [key, value] of Object.entries({
      search: state.prefs.search,
      status: state.prefs.status,
      category: state.prefs.category,
      tag: state.prefs.tag,
      tracker: state.prefs.tracker,
      sort: state.prefs.sort,
      direction: state.prefs.direction,
    })) {
      if (value && value !== DEFAULT_PREFS[key]) url.searchParams.set(key, value);
      else url.searchParams.delete(key);
    }
  } else {
    ["search", "status", "category", "tag", "tracker", "sort", "direction"].forEach((key) => url.searchParams.delete(key));
  }
  const method = replace ? "replaceState" : "pushState";
  window.history?.[method]?.({}, "", url.toString());
}

function applyUrlState() {
  resetTorrentWindow();
  const url = currentUrl();
  state.activeView = url.searchParams.get("view") === "torrents" ? "torrents" : "home";
  const search = url.searchParams.get("search");
  const status = url.searchParams.get("status");
  const category = url.searchParams.get("category");
  const tag = url.searchParams.get("tag");
  const tracker = url.searchParams.get("tracker");
  const sort = url.searchParams.get("sort");
  const direction = url.searchParams.get("direction");
  state.pendingReleaseTitle = url.searchParams.get("pendingRelease") || "";
  state.sourceHint = url.searchParams.get("source") || "";
  if (search !== null) state.prefs.search = search;
  if (status !== null) state.prefs.status = status;
  if (category !== null) state.prefs.category = category;
  if (tag !== null) state.prefs.tag = tag;
  if (tracker !== null) state.prefs.tracker = tracker;
  if (sort !== null) state.prefs.sort = sort;
  if (direction !== null) state.prefs.direction = direction;
}

function setView(view, { push = true } = {}) {
  const nextView = view === "torrents" ? "torrents" : "home";
  const changed = state.activeView !== nextView;
  state.activeView = nextView;
  els.homeView.hidden = state.activeView !== "home";
  els.torrentsView.hidden = state.activeView !== "torrents";
  els.summaryGrid.hidden = true;
  if (els.homeNavLink) {
    if (state.activeView === "home") els.homeNavLink.setAttribute("aria-current", "page");
    else els.homeNavLink.removeAttribute?.("aria-current");
  }
  if (els.torrentsNavLink) {
    if (state.activeView === "torrents") els.torrentsNavLink.setAttribute("aria-current", "page");
    else els.torrentsNavLink.removeAttribute?.("aria-current");
  }
  updateUrl(!push);
  if (changed && typeof startLive === "function") startLive();
}

function summarize(torrents) {
  const result = {
    total: torrents.length,
    downloading: 0,
    sharing: 0,
    active: 0,
    complete: 0,
    paused: 0,
    error: 0,
    downSpeed: 0,
    upSpeed: 0,
    remaining: 0,
  };
  for (const torrent of torrents) {
    const meta = stateMeta(torrent);
    if (meta.group === "downloading") result.downloading += 1;
    if (meta.group === "sharing") result.sharing += 1;
    if (["downloading", "sharing", "waiting", "checking"].includes(meta.group)) result.active += 1;
    if (isComplete(torrent)) result.complete += 1;
    if (meta.group === "paused") result.paused += 1;
    if (meta.group === "error") result.error += 1;
    result.downSpeed += Number(torrent.downloadSpeed) || 0;
    result.upSpeed += Number(torrent.uploadSpeed) || 0;
    result.remaining += Number(torrent.remaining) || Math.max(0, (Number(torrent.size) || 0) - (Number(torrent.downloaded) || 0));
  }
  return result;
}

function matchesQuickFilter(status, quickKey) {
  if (quickKey === "all") return status === "all";
  if (quickKey === "active") return ["downloading", "waiting", "checking", "sharing"].includes(status);
  return status === quickKey;
}

function renderSummary() {
  const data = summarize(state.torrents);
  const cards = [
    ["active", "Actifs", data.active],
    ["error", "Bloqués", data.error],
    [null, "Descendant", formatSpeed(data.downSpeed)],
    [null, "Montant", formatSpeed(data.upSpeed)],
    [null, "Restant", formatBytes(data.remaining)],
  ];
  const existing = Array.from(els.summaryGrid.children || []);
  const reusable = existing.length === cards.length && cards.every(([filterKey], index) =>
    existing[index]?.dataset?.summaryKey === (filterKey || "metric"));
  if (!reusable) {
    els.summaryGrid.replaceChildren(...cards.map(([filterKey, label, value]) => {
      const item = document.createElement(filterKey ? "button" : "div");
      item.className = `stat${filterKey ? " stat-button" : ""}`;
      item.dataset.summaryKey = filterKey || "metric";
      if (filterKey) {
        item.type = "button";
        item.dataset.filter = filterKey;
        item.setAttribute("aria-pressed", String(matchesQuickFilter(state.prefs.status, filterKey)));
      }
      const strong = document.createElement("strong");
      strong.textContent = value;
      const span = document.createElement("span");
      span.textContent = label;
      item.append(strong, span);
      return item;
    }));
    return;
  }
  cards.forEach(([filterKey, label, value], index) => {
    const item = existing[index];
    const strong = item.children?.[0];
    const span = item.children?.[1];
    if (strong) strong.textContent = value;
    if (span) span.textContent = label;
    if (filterKey) item.setAttribute("aria-pressed", String(matchesQuickFilter(state.prefs.status, filterKey)));
  });
}

function uniqueValues(getter) {
  return [...new Set(state.torrents.flatMap(getter).filter(Boolean))].sort((a, b) => a.localeCompare(b, "fr"));
}

function fillSelect(select, entries, value) {
  const current = value || select.value;
  const signature = JSON.stringify(entries);
  if (select.dataset?.optionsSignature !== signature) {
    select.replaceChildren(...entries.map(([optionValue, label]) => {
      const option = document.createElement("option");
      option.value = optionValue;
      option.textContent = label;
      return option;
    }));
    if (select.dataset) select.dataset.optionsSignature = signature;
  }
  select.value = entries.some(([optionValue]) => optionValue === current) ? current : entries[0]?.[0];
}

function renderQuickFilters() {
  const existing = Array.from(els.quickFilters.children || []);
  const reusable = existing.length === QUICK_FILTERS.length && QUICK_FILTERS.every((item, index) =>
    existing[index]?.dataset?.quickFilter === item.key);
  if (!reusable) {
    els.quickFilters.replaceChildren(...QUICK_FILTERS.map((item) => {
      const button = document.createElement("button");
      button.type = "button";
      button.className = `button ${matchesQuickFilter(state.prefs.status, item.key) ? "primary" : "secondary"}`;
      button.dataset.quickFilter = item.key;
      button.textContent = item.label;
      button.setAttribute("aria-pressed", String(matchesQuickFilter(state.prefs.status, item.key)));
      return button;
    }));
    return;
  }
  QUICK_FILTERS.forEach((item, index) => {
    const button = existing[index];
    const active = matchesQuickFilter(state.prefs.status, item.key);
    button.className = `button ${active ? "primary" : "secondary"}`;
    button.setAttribute("aria-pressed", String(active));
  });
}

function activeFilterLabels() {
  const labels = [];
  if (state.prefs.status !== "all") {
    const quick = QUICK_FILTERS.find((item) => matchesQuickFilter(state.prefs.status, item.key));
    labels.push(`État : ${quick?.label || STATUS_GROUPS[state.prefs.status] || state.prefs.status}`);
  }
  if (state.prefs.search.trim()) labels.push(`Recherche : ${state.prefs.search.trim()}`);
  if (state.prefs.category !== "all") labels.push(`Catégorie : ${state.prefs.category}`);
  if (state.prefs.tag !== "all") labels.push(`Tag : ${state.prefs.tag}`);
  if (state.prefs.tracker !== "all") {
    const domainCount = state.trackerIndex.domains[state.prefs.tracker];
    labels.push(`Tracker : ${state.prefs.tracker}${domainCount ? ` (${domainCount})` : ""}`);
  }
  return labels;
}

function renderFilterChips() {
  const container = document.querySelector("#activeFilters");
  if (!container) return;
  const labels = activeFilterLabels();
  const signature = JSON.stringify(labels);
  if (container.dataset?.signature === signature) return;
  container.replaceChildren(...labels.map((label) => {
      const chip = document.createElement("span");
      chip.className = "filter-chip";
      const text = document.createElement("span");
      text.textContent = label;
      const close = document.createElement("button");
      close.type = "button";
      close.textContent = "×";
      close.setAttribute("aria-label", `Retirer le filtre : ${label}`);
      close.addEventListener("click", resetFilters);
      chip.append(text, close);
      return chip;
    }));
  if (container.dataset) container.dataset.signature = signature;
}

function renderFilterNotice() {
  const labels = activeFilterLabels();
  els.filterNotice.textContent = labels.length ? `Filtres actifs : ${labels.join(" · ")}` : "Aucun filtre actif.";
  els.clearActiveFilters.hidden = labels.length === 0;
  renderFilterChips();
}

function renderFollowNotice() {
  if (!els.followNotice) return;
  if (state.sourceHint !== "prowlarr" || !state.pendingReleaseTitle) {
    els.followNotice.hidden = true;
    if (els.followNotice.children?.length) els.followNotice.replaceChildren();
    if (els.followNotice.dataset) els.followNotice.dataset.signature = "";
    return;
  }
  const signature = `${state.prowlarrPanelPrefix}|${state.pendingReleaseTitle}`;
  if (els.followNotice.dataset?.signature === signature) {
    els.followNotice.hidden = false;
    return;
  }
  const backLink = document.createElement("a");
  backLink.className = "button secondary";
  backLink.href = `${state.prowlarrPanelPrefix || "/prowlarr-panel"}/?view=search&query=${encodeURIComponent(state.pendingReleaseTitle)}`;
  backLink.textContent = "Retourner a Prowlarr";
  els.followNotice.hidden = false;
  els.followNotice.replaceChildren(
    Object.assign(document.createElement("span"), {
      textContent: `Suivi cible pour "${state.pendingReleaseTitle}". L'apparition dans qBittorrent peut prendre quelques secondes.`,
    }),
    backLink,
  );
  if (els.followNotice.dataset) els.followNotice.dataset.signature = signature;
}

function renderControls() {
  if (document.activeElement !== els.searchInput && els.searchInput.value !== state.prefs.search) {
    els.searchInput.value = state.prefs.search;
  }
  els.autoRefreshToggle.checked = state.prefs.autoRefresh;
  els.refreshInterval.value = String(state.prefs.refreshIntervalMs);
  if (document.activeElement !== els.categoryInput) els.categoryInput.value = state.prefs.lastCategory || "";
  if (document.activeElement !== els.tagsInput) els.tagsInput.value = state.prefs.lastTags || "";
  if (els.tr4kerTrackerInput && state.sourceHint === "tr4ker") els.tr4kerTrackerInput.checked = true;
  fillSelect(els.statusFilter, Object.entries(STATUS_GROUPS), state.prefs.status);
  fillSelect(els.categoryFilter, [["all", "Toutes"], ...uniqueValues((torrent) => [String(torrent.category || "").trim()]).map((value) => [value, value])], state.prefs.category);
  fillSelect(els.tagFilter, [["all", "Tous"], ...uniqueValues((torrent) => normalizeTags(torrent.tags)).map((value) => [value, value])], state.prefs.tag);
  const domainEntries = Object.entries(state.trackerIndex.domains).sort(([a], [b]) => a.localeCompare(b, "fr"));
  fillSelect(els.trackerFilter, [["all", "Tous les trackers"], ["__none__", "Sans tracker"], ...domainEntries.map(([domain, count]) => [domain, `${domain} — ${count}`])], state.prefs.tracker);
  fillSelect(els.sortSelect, Object.entries(SORT_LABELS), state.prefs.sort);
  if (els.sortDirectionSelect) els.sortDirectionSelect.value = state.prefs.direction;
  if (els.densityToggle) {
    const compact = state.prefs.density === "compact";
    const panel = document.querySelector(".torrents-panel");
    if (panel) {
      if (compact) panel.classList.add("compact");
      else panel.classList.remove("compact");
    }
    els.densityToggle.setAttribute("aria-pressed", String(compact));
    els.densityToggle.textContent = compact ? "Vue normale" : "Vue compacte";
  }
  renderQuickFilters();
  renderFilterNotice();
  renderFollowNotice();
}

function filteredTorrents() {
  const search = state.prefs.search.trim().toLocaleLowerCase("fr");
  const filtered = state.torrents.filter((torrent) => {
    const meta = stateMeta(torrent);
    if (search && !String(torrent.name || "").toLocaleLowerCase("fr").includes(search)) return false;
    if (state.prefs.status === "complete" && !isComplete(torrent)) return false;
    if (state.prefs.status === "active" && !["downloading", "waiting", "checking", "sharing"].includes(meta.group)) return false;
    if (!["all", "complete", "active"].includes(state.prefs.status) && meta.group !== state.prefs.status) return false;
    if (state.prefs.category !== "all" && String(torrent.category || "") !== state.prefs.category) return false;
    if (state.prefs.tag !== "all" && !normalizeTags(torrent.tags).includes(state.prefs.tag)) return false;
    if (state.prefs.tracker === "__none__") {
      const trackerDomains = state.trackerIndex.index[torrent.hash];
      if (trackerDomains && trackerDomains.length > 0) return false;
    } else if (state.prefs.tracker !== "all") {
      const trackerDomains = state.trackerIndex.index[torrent.hash];
      if (!trackerDomains || !trackerDomains.includes(state.prefs.tracker)) return false;
    }
    return true;
  });
  return sortTorrents(filtered);
}

function resetTorrentWindow() {
  state.renderOffset = 0;
}

function torrentWindow(visible) {
  const maxOffset = visible.length
    ? Math.floor((visible.length - 1) / state.renderLimit) * state.renderLimit
    : 0;
  state.renderOffset = Math.min(state.renderOffset, maxOffset);
  return visible.slice(state.renderOffset, state.renderOffset + state.renderLimit);
}

function renderedTorrents() {
  return torrentWindow(filteredTorrents());
}

function sortValue(torrent, key) {
  if (key === "state") return GROUP_ORDER[stateMeta(torrent).group] ?? 99;
  if (key === "name") return String(torrent.name || "").toLocaleLowerCase("fr");
  return Number(torrent[key]) || 0;
}

function sortTorrents(torrents) {
  const key = state.prefs.sort;
  const direction = state.prefs.direction === "desc" ? -1 : 1;
  return [...torrents].sort((leftTorrent, rightTorrent) => {
    if (key === "default") {
      const groupDiff = (GROUP_ORDER[stateMeta(leftTorrent).group] ?? 99) - (GROUP_ORDER[stateMeta(rightTorrent).group] ?? 99);
      if (groupDiff) return groupDiff * direction;
      return ((Number(rightTorrent.downloadSpeed) || 0) - (Number(leftTorrent.downloadSpeed) || 0)) * direction;
    }
    const left = sortValue(leftTorrent, key);
    const right = sortValue(rightTorrent, key);
    if (typeof left === "string" || typeof right === "string") return String(left).localeCompare(String(right), "fr") * direction;
    return (left - right) * direction;
  });
}

function setStatusFromQuickFilter(filterKey) {
  resetTorrentWindow();
  state.prefs.status = filterKey;
  savePrefs();
  updateUrl();
  render();
}

function setSort(key) {
  resetTorrentWindow();
  if (state.prefs.sort === key) {
    state.prefs.direction = state.prefs.direction === "asc" ? "desc" : "asc";
  } else {
    state.prefs.sort = key;
    state.prefs.direction = key === "name" ? "asc" : "desc";
  }
  savePrefs();
  updateUrl();
  render();
}

function button(label, className, onClick) {
  const el = document.createElement("button");
  el.type = "button";
  el.className = `button ${className}`;
  el.textContent = label;
  el.addEventListener("click", onClick);
  return el;
}

function quickActionButton(item) {
  const action = button(item.label, "secondary", async (event) => {
    const trigger = event.currentTarget;
    trigger.disabled = true;
    const previous = trigger.textContent;
    trigger.textContent = "Lancement…";
    state.actionRevision += 1;
    try {
      const payload = await api(`api/media-actions/${item.actionId}`, { method: "POST" });
      showToast(payload.message || "Action lancée.");
      await loadTorrents({ silent: true, force: true });
    } catch (error) {
      showError(error);
    } finally {
      trigger.disabled = false;
      trigger.textContent = previous;
      resumeLiveAfterAction();
    }
  });
  action.className = "quick-action quick-action-button";
  const title = document.createElement("strong");
  title.textContent = item.label;
  const subtitle = document.createElement("span");
  subtitle.textContent = item.description || "Déclenche une action backend.";
  action.replaceChildren(title, subtitle);
  return action;
}

function actionLink(action) {
  const link = document.createElement("a");
  link.className = "button secondary";
  link.href = action?.url || `${route("/")}?view=home`;
  link.textContent = action?.label || "Afficher";
  return link;
}

function renderBadge(meta) {
  const badge = document.createElement("span");
  badge.className = `badge ${meta.group}`;
  const icon = document.createElement("span");
  icon.className = "badge-icon";
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = meta.icon;
  const text = document.createElement("span");
  text.textContent = meta.text;
  badge.append(icon, text);
  return badge;
}

function renderProgress(torrent) {
  const progress = Math.max(0, Math.min(100, (Number(torrent.progress) || 0) * 100));
  const wrap = document.createElement("div");
  wrap.className = "progress-wrap";
  const track = document.createElement("div");
  track.className = "progress-track";
  track.setAttribute("role", "progressbar");
  track.setAttribute("aria-valuemin", "0");
  track.setAttribute("aria-valuemax", "100");
  track.setAttribute("aria-valuenow", progress.toFixed(1));
  const bar = document.createElement("div");
  bar.className = "progress-bar";
  bar.style.width = `${progress}%`;
  const text = document.createElement("div");
  text.className = "progress-text";
  text.textContent = `${progress.toFixed(1)} %`;
  track.append(bar);
  wrap.append(track, text);
  return wrap;
}

function renderRow(torrent) {
  const meta = stateMeta(torrent);
  const hash = torrent.hash;
  const busyText = state.rowBusy.get(hash);
  const tr = document.createElement("tr");
  tr.dataset.hash = hash;
  if (busyText) tr.classList.add("is-busy");

  const selectTd = document.createElement("td");
  selectTd.dataset.label = "Sélection";
  selectTd.dataset.cell = "select";
  const checkbox = document.createElement("input");
  checkbox.type = "checkbox";
  checkbox.checked = state.selected.has(hash);
  checkbox.disabled = Boolean(busyText);
  checkbox.dataset.focusKey = "select";
  checkbox.setAttribute("aria-label", `Sélectionner ${torrent.name}`);
  checkbox.addEventListener("change", () => {
    if (checkbox.checked) state.selected.add(hash);
    else state.selected.delete(hash);
    renderSelection();
  });
  selectTd.append(checkbox);

  const nameTd = document.createElement("td");
  nameTd.dataset.label = "Nom";
  nameTd.dataset.cell = "name";
  const nameButton = document.createElement("button");
  nameButton.type = "button";
  nameButton.className = "name-button";
  nameButton.title = torrent.name;
  nameButton.dataset.focusKey = "name";
  const searchQuery = String(state.prefs.search || "").trim().toLowerCase();
  if (searchQuery && String(torrent.name || "").toLowerCase().includes(searchQuery)) {
    const idx = String(torrent.name).toLowerCase().indexOf(searchQuery);
    nameButton.append(
      document.createTextNode(String(torrent.name).slice(0, idx)),
      Object.assign(document.createElement("mark"), { className: "search-hit", textContent: String(torrent.name).slice(idx, idx + searchQuery.length) }),
      document.createTextNode(String(torrent.name).slice(idx + searchQuery.length)),
    );
  } else {
    nameButton.textContent = torrent.name;
  }
  nameButton.addEventListener("click", (event) => openDetails(torrent.hash, event.currentTarget));
  nameTd.append(nameButton);

  const stateTd = document.createElement("td");
  stateTd.dataset.label = "État";
  stateTd.dataset.cell = "state";
  stateTd.append(renderBadge(meta));

  const progressTd = document.createElement("td");
  progressTd.dataset.label = "Progression";
  progressTd.className = "progress-cell";
  progressTd.dataset.cell = "progress";
  progressTd.append(renderProgress(torrent));

  const downTd = textCell("Téléchargement", formatSpeed(torrent.downloadSpeed), "mono", "download-speed");
  const upTd = textCell("Envoi", formatSpeed(torrent.uploadSpeed), "mono", "upload-speed");
  const uploadedTd = textCell("Uploadé", formatBytes(torrent.uploaded), "mono", "uploaded");
  const ratioTd = textCell("Ratio", formatRatio(torrent.ratio), "mono", "ratio");
  const sizeTd = textCell("Taille", formatBytes(torrent.size), "mono", "size");
  const etaTd = textCell("ETA", formatEta(torrent.eta), "mono", "eta");
  const addedTd = textCell("Ajout", formatDate(torrent.addedOn), "mono", "added");

  const actionTd = document.createElement("td");
  actionTd.dataset.label = "Actions";
  actionTd.dataset.cell = "actions";
  const actions = document.createElement("div");
  actions.className = "action-row";
  const isPaused = meta.group === "paused";
  const isForcedShare = torrent.state === "forcedUP";
  const canForceShare = isComplete(torrent) || isForcedShare;
  const pauseOrResume = button(isPaused ? "Reprendre" : "Pause", isPaused ? "primary" : "secondary", () => runTorrentAction([hash], isPaused ? "resume" : "pause"));
  const detail = button("Détails", "secondary", (event) => openDetails(hash, event.currentTarget));
  const organize = isComplete(torrent)
    ? button("Ranger ce torrent", "secondary", (event) => openOrganizeMediaDialog([hash], event.currentTarget))
    : null;
  const forceShare = canForceShare
    ? button(isForcedShare ? "Partage normal" : "Partage forcé", isForcedShare ? "primary" : "secondary", () => runTorrentAction([hash], "force-start", { enabled: !isForcedShare }))
    : null;
  const remove = button("Supprimer", "danger", (event) => openDeleteDialog([torrent], event.currentTarget));
  pauseOrResume.dataset.focusKey = "toggle";
  detail.dataset.focusKey = "details";
  if (organize) organize.dataset.focusKey = "organize";
  if (forceShare) forceShare.dataset.focusKey = "force-share";
  remove.dataset.focusKey = "delete";
  for (const control of [pauseOrResume, detail, organize, forceShare, remove].filter(Boolean)) control.disabled = Boolean(busyText);
  actions.append(...[pauseOrResume, detail, organize, forceShare, remove].filter(Boolean));
  const inline = document.createElement("div");
  inline.className = "row-status";
  inline.setAttribute("aria-live", "polite");
  inline.textContent = busyText || state.rowErrors.get(hash) || "";
  actionTd.append(actions, inline);

  tr.append(selectTd, nameTd, stateTd, progressTd, downTd, upTd, uploadedTd, ratioTd, sizeTd, etaTd, addedTd, actionTd);
  return tr;
}

function captureTorrentRowFocus() {
  const active = document.activeElement;
  if (!active || !els.rows?.contains?.(active)) return null;
  const row = active.closest?.("tr[data-hash]");
  if (!row) return null;
  return { hash: String(row.dataset.hash || ""), focusKey: String(active.dataset?.focusKey || "") };
}

function restoreTorrentRowFocus(record) {
  if (!record?.hash) return;
  const row = [...(els.rows.children || [])].find((item) => String(item.dataset?.hash || "") === record.hash);
  if (!row) return;
  const controls = row.querySelectorAll ? [...row.querySelectorAll("[data-focus-key]")] : [];
  const target = controls.find((item) => item.dataset?.focusKey === record.focusKey)
    || controls.find((item) => item.dataset?.focusKey === "name")
    || row;
  target?.focus?.({ preventScroll: true });
}

function torrentRowSignature(torrent) {
  const meta = stateMeta(torrent);
  return JSON.stringify([
    String(torrent.hash || ""),
    String(torrent.name || ""),
    String(torrent.state || ""),
    meta.group,
    isComplete(torrent),
    state.rowBusy.get(torrent.hash) || "",
    state.rowErrors.get(torrent.hash) || "",
    state.prefs.search,
  ]);
}

function syncTorrentRowSelection(row, hash) {
  const checkbox = row.querySelector?.('input[type="checkbox"]');
  if (!checkbox) return;
  checkbox.checked = state.selected.has(hash);
  checkbox.disabled = state.rowBusy.has(hash);
}

function updateTorrentRowValues(row, torrent) {
  const findCell = (key) => row.querySelector?.(`[data-cell="${key}"]`);
  const setText = (key, value) => {
    const cell = findCell(key);
    if (cell) cell.textContent = value;
  };
  syncTorrentRowSelection(row, String(torrent.hash));
  setText("download-speed", formatSpeed(torrent.downloadSpeed));
  setText("upload-speed", formatSpeed(torrent.uploadSpeed));
  setText("uploaded", formatBytes(torrent.uploaded));
  setText("ratio", formatRatio(torrent.ratio));
  setText("size", formatBytes(torrent.size));
  setText("eta", formatEta(torrent.eta));
  setText("added", formatDate(torrent.addedOn));

  const progressCell = findCell("progress");
  const progress = Math.max(0, Math.min(100, (Number(torrent.progress) || 0) * 100));
  const track = progressCell?.querySelector?.('[role="progressbar"]');
  const bar = track?.querySelector?.(".progress-bar");
  const label = progressCell?.querySelector?.(".progress-text");
  if (track) track.setAttribute("aria-valuenow", progress.toFixed(1));
  if (bar) bar.style.width = `${progress}%`;
  if (label) label.textContent = `${progress.toFixed(1)} %`;
}

function renderTorrentRows(visible) {
  const focused = captureTorrentRowFocus();
  const scrollShell = els.rows?.closest?.(".torrent-table-shell");
  const previousScrollTop = scrollShell?.scrollTop;
  const previousNodes = [...(els.rows.children || [])];
  const rendered = torrentWindow(visible);
  const windowChanged = state.renderedOffset !== state.renderOffset;
  const nextNodes = [];
  const nextNodeMap = new Map();
  const nextSignatureMap = new Map();
  for (const torrent of rendered) {
    const hash = String(torrent.hash);
    const signature = torrentRowSignature(torrent);
    let row = state.rowNodes.get(hash);
    if (!row || state.rowSignatures.get(hash) !== signature) {
      row = renderRow(torrent);
    } else {
      updateTorrentRowValues(row, torrent);
    }
    nextNodes.push(row);
    nextNodeMap.set(hash, row);
    nextSignatureMap.set(hash, signature);
  }
  const orderChanged = previousNodes.length !== nextNodes.length
    || previousNodes.some((node, index) => node !== nextNodes[index]);
  if (orderChanged) els.rows.replaceChildren(...nextNodes);
  state.rowNodes = nextNodeMap;
  state.rowSignatures = nextSignatureMap;
  const sameRowSet = previousNodes.length === nextNodes.length
    && previousNodes.every((node) => nextNodeMap.has(String(node.dataset?.hash || "")));
  if (windowChanged && scrollShell) {
    scrollShell.scrollTop = 0;
  } else if (sameRowSet && scrollShell && Number.isFinite(previousScrollTop)) {
    scrollShell.scrollTop = previousScrollTop;
  }
  state.renderedOffset = state.renderOffset;
  restoreTorrentRowFocus(focused);
  return rendered;
}

function renderTorrentRowLimit(visible, rendered) {
  const hasPrevious = state.renderOffset > 0;
  const remaining = Math.max(0, visible.length - state.renderOffset - rendered.length);
  if (els.showPreviousRows) els.showPreviousRows.hidden = !hasPrevious;
  if (els.loadMoreRows) {
    els.loadMoreRows.hidden = remaining === 0;
    if (remaining > 0) {
      const amount = Math.min(MAX_RENDERED_TORRENTS, remaining);
      els.loadMoreRows.textContent = "Afficher " + amount + " torrent" + (amount > 1 ? "s" : "") + " suivants";
    }
  }
}

function textCell(label, value, className = "", cellKey = "") {
  const td = document.createElement("td");
  td.dataset.label = label;
  td.className = className;
  if (cellKey) td.dataset.cell = cellKey;
  td.textContent = value;
  return td;
}

function renderSelection(visible = renderedTorrents()) {
  for (const hash of [...state.selected]) {
    if (!state.torrents.some((torrent) => torrent.hash === hash)) state.selected.delete(hash);
  }
  const visibleHashes = visible.map((torrent) => torrent.hash);
  const selectedVisible = visibleHashes.filter((hash) => state.selected.has(hash));
  const allVisibleSelected = visibleHashes.length > 0 && selectedVisible.length === visibleHashes.length;
  els.selectVisible.checked = allVisibleSelected;
  els.selectVisible.indeterminate = selectedVisible.length > 0 && selectedVisible.length < visibleHashes.length;
  els.selectVisible.disabled = visibleHashes.length === 0;
  els.selectVisibleLabel.textContent = allVisibleSelected ? "Tout désélectionner" : "Tout sélectionner";
  els.visibleSelectionSummary.textContent = visibleHashes.length
    ? `${selectedVisible.length} sur ${visibleHashes.length} sélectionné${selectedVisible.length > 1 ? "s" : ""}`
    : "Aucun torrent affiché";
  els.bulkBar.hidden = state.selected.size === 0;
  els.bulkCount.textContent = `${state.selected.size} sélectionné${state.selected.size > 1 ? "s" : ""}`;
}

function renderSortHeaders() {
  document.querySelectorAll(".sort-head").forEach((head) => {
    const key = head.dataset.sort;
    const active = key === state.prefs.sort;
    head.setAttribute("aria-sort", active ? (state.prefs.direction === "asc" ? "ascending" : "descending") : "none");
    const label = head.textContent.replace(/\s+[↑↓]$/, "").trim();
    const arrowAsc = `<svg class="sort-arrow" width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M5 2v6M3 5l2-3 2 3" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    const arrowDesc = `<svg class="sort-arrow" width="10" height="10" viewBox="0 0 10 10" aria-hidden="true"><path d="M5 2v6M3 5l2 3 2-3" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
    head.innerHTML = active
      ? `${label} ${state.prefs.direction === "asc" ? arrowAsc : arrowDesc}`
      : label;
  });
}

function createSvgIcon(name) {
  const span = document.createElement("span");
  span.className = `ui-icon ui-icon-${name}`;
  span.setAttribute("aria-hidden", "true");
  const icons = {
    speed: `<svg viewBox="0 0 24 24"><path d="M4 15.5 9 10.5l3.5 3.5L20 6.5"></path><path d="M14 6.5h6v6"></path></svg>`,
    torrents: `<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.25"></circle><path d="M12 7v8m0 0 3-3m-3 3-3-3"></path></svg>`,
    indexers: `<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.25"></circle><path d="M3.75 12h16.5M12 3.75c2.5 2.6 3.75 5.35 3.75 8.25S14.5 17.65 12 20.25M12 3.75c-2.5 2.6-3.75 5.35-3.75 8.25S9.5 17.65 12 20.25"></path></svg>`,
    jellyfin: `<svg viewBox="0 0 24 24"><path d="m12 4 7 14H5z"></path><path d="m12 9 2.75 5.5h-5.5z"></path></svg>`,
    qBittorrent: `<svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="8.25"></circle><path d="M8.5 8.5v7M15.5 8.5v7M8.5 12c0-1.93 1.57-3.5 3.5-3.5 1.8 0 3.28 1.36 3.47 3.11"></path></svg>`,
    prowlarr: `<svg viewBox="0 0 24 24"><path d="m12 4 6.75 3.9v8.2L12 20l-6.75-3.9V7.9z"></path><path d="m12 4 6.75 12.1M12 4 5.25 16.1M5.25 7.9 12 12l6.75-4.1M12 12v8"></path></svg>`,
    rclone: `<svg viewBox="0 0 24 24"><path d="M8.5 18.25h8.25a3.25 3.25 0 0 0 .6-6.44A4.75 4.75 0 0 0 8 10.5a3.5 3.5 0 0 0 .5 6.94Z"></path></svg>`,
    download: `<svg viewBox="0 0 24 24"><path d="M12 4v10m0 0 3.5-3.5M12 14l-3.5-3.5M5 18.25h14"></path></svg>`,
    upload: `<svg viewBox="0 0 24 24"><path d="M12 20V10m0 0 3.5 3.5M12 10l-3.5 3.5M5 5.75h14"></path></svg>`,
    alert: `<svg viewBox="0 0 24 24"><path d="m12 4 8 14H4z"></path><path d="M12 9v4.5M12 17h.01"></path></svg>`,
    scan: `<svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4.25 4.25"></path></svg>`,
    play: `<svg viewBox="0 0 24 24"><path d="m9 7 8 5-8 5z"></path></svg>`,
  };
  span.innerHTML = icons[name] || icons.scan;
  return span;
}

function renderAlerts() {
  const alerts = Array.isArray(state.dashboard.alerts) ? state.dashboard.alerts : [];
  const critical = alerts.filter((item) => item.severity === "critical");
  els.navAlertCount.hidden = critical.length === 0;
  els.navAlertCount.textContent = String(critical.length);
  els.criticalAlerts.hidden = critical.length === 0;
  els.criticalAlerts.replaceChildren(
    ...critical.map((item) => {
      const article = document.createElement("article");
      article.className = "alert-item critical";
      const head = document.createElement("div");
      head.className = "alert-head";
      const title = document.createElement("strong");
      title.textContent = item.service;
      const severity = document.createElement("span");
      severity.className = "severity-pill critical";
      severity.textContent = "Critique";
      head.append(title, severity);
      const text = document.createElement("p");
      text.textContent = item.message;
      article.append(head, text, actionLink(item.action));
      return article;
    }),
  );
}

function createSystemState(type, title, message, options = {}) {
  if (window.DashboardDOM?.state) {
    return window.DashboardDOM.state({ type, title, message, compact: options.compact !== false });
  }
  const node = document.createElement("div");
  node.className = `system-state ${type}${options.compact !== false ? " compact" : ""}`;
  node.setAttribute("role", type === "error" || type === "unavailable" ? "alert" : "status");
  const titleNode = document.createElement("p");
  titleNode.className = "system-state-title";
  titleNode.textContent = title;
  const messageNode = document.createElement("p");
  messageNode.className = "system-state-message";
  messageNode.textContent = message;
  node.append(titleNode, messageNode);
  return node;
}

function renderServices() {
  const services = Array.isArray(state.dashboard.services) ? state.dashboard.services : [];
  const orderedNames = ["qBittorrent", "Prowlarr", "rclone", "Jellyfin"];
  const visibleServices = orderedNames
    .map((name) => services.find((item) => String(item.name || "").toLowerCase() === name.toLowerCase()))
    .filter(Boolean);
  const operational = services.filter((item) => item.status === "operational").length;
  els.servicesSummary.textContent = services.length
    ? `${operational}/${services.length} service(s) opérationnel(s).`
    : "Statuts indisponibles.";
  if (!visibleServices.length) {
    els.servicesGrid.replaceChildren(createSystemState(
      "unavailable",
      "Services indisponibles",
      "Les statuts qBittorrent, Prowlarr, rclone et Jellyfin réapparaîtront à la prochaine synchronisation.",
    ));
    return;
  }
  els.servicesGrid.replaceChildren(
    ...visibleServices.map((item) => {
      const link = document.createElement(item.action?.url ? "a" : "div");
      link.className = `service-row ${item.status || "checking"}${item.action?.url ? " card-interactive" : ""}`;
      if (item.action?.url) link.href = item.action.url;
      const left = document.createElement("div");
      left.className = "service-row-main";
      left.append(
        createSvgIcon(item.name === "qBittorrent" ? "qBittorrent" : String(item.name || "").toLowerCase()),
      );
      const copy = document.createElement("div");
      copy.className = "service-row-copy";
      const title = document.createElement("strong");
      title.textContent = item.name;
      const meta = document.createElement("span");
      meta.textContent = formatRelativeTime(item.checkedAt);
      copy.append(title, meta);
      left.append(copy);
      const status = document.createElement("div");
      status.className = "service-row-status";
      const dot = document.createElement("span");
      dot.className = `status-dot ${item.status || "checking"}`;
      const text = document.createElement("span");
      text.textContent = item.status === "operational"
        ? "Opérationnel"
        : item.status === "degraded"
          ? "Dégradé"
          : item.status === "checking"
            ? "En attente"
            : "Indisponible";
      status.append(dot, text);
      link.append(left, status);
      return link;
    }).slice(0, 4),
  );
}

function pushMetricHistory(key, value) {
  const series = state.metricHistory[key] || [];
  const numeric = Number(value);
  if (!Number.isFinite(numeric)) return;
  series.push(numeric);
  if (series.length > 16) series.shift();
  state.metricHistory[key] = series;
}

function sparklineSvg(points) {
  const values = points.length >= 2 ? points : [0, 0];
  const min = Math.min(...values);
  const max = Math.max(...values);
  const range = max - min || 1;
  const path = values.map((value, index) => {
    const x = (index / Math.max(values.length - 1, 1)) * 100;
    const y = 100 - ((value - min) / range) * 72 - 14;
    return `${index === 0 ? "M" : "L"} ${x.toFixed(2)} ${y.toFixed(2)}`;
  }).join(" ");
  const fillPath = values.length > 1
    ? `M${(0).toFixed(2)} 100 L${path.slice(1)} L${((values.length - 1) / Math.max(values.length - 1, 1) * 100).toFixed(2)} 100 Z`
    : "";
  const lastX = values.length > 1 ? ((values.length - 1) / Math.max(values.length - 1, 1) * 100).toFixed(2) : "0";
  const lastY = 100 - ((values.at(-1) - min) / range) * 72 - 14;
  return `<svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true">`
    + (fillPath ? `<path d="${fillPath}" fill="var(--accent)" opacity="0.08" pathLength="100"></path>` : "")
    + `<path d="${path}" pathLength="100"></path>`
    + `<circle cx="${lastX}" cy="${lastY.toFixed(2)}" r="3" fill="var(--accent)" opacity="0"></circle>`
    + `</svg>`;
}

function trendText(points) {
  if (points.length < 2) return "Historique en cours";
  const diff = points.at(-1) - points.at(0);
  if (Math.abs(diff) < 0.001) return "Tendance stable";
  return diff > 0 ? "Tendance en hausse" : "Tendance en baisse";
}

function renderOverviewMetrics() {
  const overview = state.dashboard.overview || {};
  const hasMetric = (key) => Number.isFinite(Number(overview[key]));
  if (hasMetric("downloadSpeedBytes")) pushMetricHistory("downloadSpeedBytes", Number(overview.downloadSpeedBytes));
  if (hasMetric("uploadSpeedBytes")) pushMetricHistory("uploadSpeedBytes", Number(overview.uploadSpeedBytes));
  if (hasMetric("activeTorrents")) pushMetricHistory("activeTorrents", Number(overview.activeTorrents));
  const cards = [
    {
      label: "Débit descendant",
      value: hasMetric("downloadSpeedBytes") ? formatSpeed(overview.downloadSpeedBytes) : "Indisponible",
      meta: "Téléchargement actuel",
      icon: "download",
      historyKey: "downloadSpeedBytes",
      available: hasMetric("downloadSpeedBytes"),
    },
    {
      label: "Débit montant",
      value: hasMetric("uploadSpeedBytes") ? formatSpeed(overview.uploadSpeedBytes) : "Indisponible",
      meta: "Envoi actuel",
      icon: "upload",
      historyKey: "uploadSpeedBytes",
      available: hasMetric("uploadSpeedBytes"),
    },
    {
      label: "Torrents actifs",
      value: hasMetric("activeTorrents") ? String(overview.activeTorrents) : "Indisponible",
      meta: "Téléchargements et partages",
      icon: "speed",
      historyKey: "activeTorrents",
      available: hasMetric("activeTorrents"),
    },
  ];
  els.overviewMetrics.replaceChildren(
    ...cards.map((card) => {
      const article = document.createElement("article");
      article.className = `overview-card metric-card${card.available ? "" : " unavailable"}`;
      const top = document.createElement("div");
      top.className = "metric-top";
      const iconWrap = document.createElement("div");
      iconWrap.className = "metric-icon";
      iconWrap.append(createSvgIcon(card.icon));
      const copy = document.createElement("div");
      copy.className = "metric-copy";
      copy.append(
        Object.assign(document.createElement("span"), { className: "metric-label", textContent: card.label }),
        Object.assign(document.createElement("strong"), { className: "metric-value", textContent: card.value }),
      );
      top.append(iconWrap, copy);
      const sparkline = document.createElement("div");
      sparkline.className = "sparkline";
      const history = state.metricHistory[card.historyKey] || [];
      if (card.available) {
        sparkline.innerHTML = sparklineSvg(history);
        sparkline.setAttribute("aria-label", trendText(history));
      } else {
        sparkline.replaceChildren(createSystemState("unavailable", "Donnée absente", "En attente du backend.", { compact: true }));
      }
      article.append(top, sparkline, Object.assign(document.createElement("p"), { className: "metric-meta", textContent: card.meta }));
      return article;
    }),
  );
}

function renderRecentActivity() {
  const items = Array.isArray(state.dashboard.recentActivity) && state.dashboard.recentActivity.length
    ? state.dashboard.recentActivity
    : (state.activity.timeline || []).slice(0, 3).map((item) => ({
        date: item.date,
        service: item.service,
        title: item.message,
        detail: item.type,
        kind: item.type === "download_completed" ? "download" : "scan",
        status: item.result === "critical" ? "danger" : "success",
      }));
  els.activitySummary.textContent = items.length
    ? `${items.length} événement(s) récents affichés.`
    : "Aucun événement récent disponible.";
  if (!items.length) {
    els.activityList.replaceChildren(createSystemState(
      "empty",
      "Aucune activité récente",
      "Les événements de téléchargement, scan et stockage apparaîtront ici dès qu’ils seront disponibles.",
    ));
    return;
  }
  els.activityList.replaceChildren(
    ...items.slice(0, 3).map((item) => {
      const article = document.createElement("article");
      article.className = "activity-item";
      const icon = document.createElement("div");
      icon.className = `activity-icon ${item.status || "success"}`;
      icon.append(createSvgIcon(item.kind === "download" ? "download" : item.kind === "alert" ? "alert" : item.kind === "play" ? "play" : "scan"));
      const copy = document.createElement("div");
      copy.className = "activity-copy";
      const title = document.createElement("strong");
      title.textContent = item.title || "Événement";
      const detail = document.createElement("p");
      detail.textContent = `${item.service || "Service"} · ${item.detail || "Mise à jour"}`;
      const meta = document.createElement("span");
      meta.textContent = formatRelativeTime(item.date);
      copy.append(title, detail, meta);
      article.append(icon, copy);
      return article;
    }),
  );
}

function workflowBadge(status) {
  const mapping = {
    pending: { group: "waiting", text: "En attente", icon: "…" },
    rclone_refresh: { group: "checking", text: "Actualisation rclone", icon: "…" },
    mount_wait: { group: "checking", text: "Attente du montage", icon: "…" },
    jellyfin_requested: { group: "checking", text: "Scan Jellyfin demandé", icon: "…" },
    completed: { group: "complete", text: "Terminé", icon: "✓" },
    partial_failure: { group: "error", text: "Échec partiel", icon: "!" },
    failed: { group: "error", text: "Échec définitif", icon: "!" },
  };
  return renderBadge(mapping[status] || mapping.pending);
}

function retryWorkflow(entryId, scope, trigger) {
  if (trigger) {
    trigger.disabled = true;
    trigger.textContent = "Relance…";
  }
  state.actionRevision += 1;
  return api(`api/media-workflows/${entryId}/retry`, {
    method: "POST",
    body: JSON.stringify({ scope }),
  }).then(async () => {
    showToast(scope === "jellyfin" ? "Scan Jellyfin relancé." : "Workflow relancé.");
    await loadTorrents({ silent: true, force: true });
  }).catch((error) => {
    showError(error);
  }).finally(() => {
    resumeLiveAfterAction();
    if (trigger) {
      trigger.disabled = false;
      trigger.textContent = scope === "jellyfin" ? "Relancer Jellyfin" : "Réessayer";
    }
  });
}

function renderHome() {
  const backendStatus = state.backendStatus || BACKEND_STATES.loading;
  if (backendStatus === BACKEND_STATES.loading || backendStatus === BACKEND_STATES.unavailable || backendStatus === BACKEND_STATES.empty) {
    const unavailable = backendStatus === BACKEND_STATES.unavailable;
    const empty = backendStatus === BACKEND_STATES.empty;
    els.homeTitle.innerHTML = unavailable ? "Backend indisponible." : empty ? "Aucune donnée pour le moment." : "Vérification en cours.";
    els.homeSummary.textContent = unavailable
      ? "Le backend Torrent ne répond pas. Les données affichées ne sont pas disponibles."
      : empty
        ? "La connexion est prête, mais aucun torrent ou service n’a encore remonté de données."
        : "Connexion aux services en cours de vérification.";
    els.homeStatusBadge?.classList.toggle("is-warning", unavailable);
    els.homeStatusText.textContent = unavailable ? "Services indisponibles" : empty ? "Aucune donnée" : "Vérification en cours";
    if (els.statusText) els.statusText.textContent = unavailable ? "Backend indisponible" : empty ? "Aucune donnée" : "Vérification en cours";
    if (els.sidebarStatusDetail) els.sidebarStatusDetail.textContent = unavailable ? "Réessayez pour relancer la vérification." : empty ? "Aucune donnée remontée." : "Connexion en cours…";
    renderAlerts(); renderOverviewMetrics(); renderServices(); renderRecentActivity();
    return;
  }
  const critical = Number(state.dashboard.criticalCount || 0);
  const operationalServices = (state.dashboard.services || []).filter((item) => item.status === "operational").length;
  const totalServices = (state.dashboard.services || []).length;
  els.homeTitle.innerHTML = critical ? "Une attention est requise." : "Tout fonctionne.<br>Parfaitement.";
  els.homeSummary.textContent = critical
    ? `${critical} alerte(s) critique(s) demandent une attention immédiate.`
    : "Aucune alerte critique. Les services restent surveillés en direct.";
  if (els.homeStatusBadge?.classList) {
    if (critical > 0) els.homeStatusBadge.classList.add("is-warning");
    else els.homeStatusBadge.classList.remove("is-warning");
  }
  els.homeStatusText.textContent = critical
    ? `${critical} incident(s) nécessitent une action`
    : "Tous les services sont opérationnels";
  const greeting = document.querySelector("#greeting");
  if (greeting) {
    const hour = new Date().getHours();
    greeting.textContent = hour >= 6 && hour < 12 ? "Bonjour"
      : hour >= 12 && hour < 18 ? "Bon après-midi"
      : "Bonsoir";
  }
  if (els.statusText) {
    els.statusText.textContent = critical
      ? `${critical} alerte(s) critique(s)`
      : "Tous les services sont opérationnels";
  }
  if (els.sidebarStatusDetail) {
    els.sidebarStatusDetail.textContent = totalServices
      ? `${operationalServices}/${totalServices} services surveillés.`
      : "Surveillance en direct.";
  }
  renderAlerts();
  renderOverviewMetrics();
  renderServices();
  renderRecentActivity();
}

function renderBandwidthChart() {
  const svg = document.querySelector("#bandwidthSvg");
  if (!svg) return;
  const dl = state.metricHistory.downloadSpeedBytes || [];
  const ul = state.metricHistory.uploadSpeedBytes || [];
  const len = Math.max(dl.length, ul.length);
  if (len < 2) {
    svg.replaceChildren();
    return;
  }
  const padL = 10, padR = 10, padT = 8, padB = 20;
  const w = 400, h = 160;
  const plotW = w - padL - padR;
  const plotH = h - padT - padB;
  function seriesPath(data) {
    const max = Math.max(...data, 1);
    return data.map((v, i) => {
      const x = padL + (i / Math.max(data.length - 1, 1)) * plotW;
      const y = padT + plotH - (v / max) * plotH;
      return `${i === 0 ? "M" : "L"} ${x.toFixed(1)} ${y.toFixed(1)}`;
    }).join(" ");
  }
  function fillPath(data) {
    const max = Math.max(...data, 1);
    const firstX = padL;
    const lastX = padL + ((data.length - 1) / Math.max(data.length - 1, 1)) * plotW;
    const pts = data.map((v, i) => {
      const x = padL + (i / Math.max(data.length - 1, 1)) * plotW;
      const y = padT + plotH - (v / max) * plotH;
      return `${x.toFixed(1)},${y.toFixed(1)}`;
    }).join(" ");
    return `M${firstX.toFixed(1)},${(padT + plotH).toFixed(1)} L${pts} L${lastX.toFixed(1)},${(padT + plotH).toFixed(1)} Z`;
  }
  svg.innerHTML = ""
    + `<path d="${fillPath(dl)}" fill="var(--accent)" opacity="0.08"></path>`
    + `<path d="${seriesPath(dl)}" fill="none" stroke="var(--accent)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>`
    + `<path d="${fillPath(ul)}" fill="var(--success)" opacity="0.06"></path>`
    + `<path d="${seriesPath(ul)}" fill="none" stroke="var(--success)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"></path>`;
  const dlEl = document.querySelector("#bandwidthDl");
  const ulEl = document.querySelector("#bandwidthUl");
  if (dlEl) dlEl.textContent = formatSpeed((dl.at(-1) || 0));
  if (ulEl) ulEl.textContent = formatSpeed((ul.at(-1) || 0));
}

function render() {
  renderSummary();
  renderControls();
  if (state.activeView === "home") renderHome();
  setView(state.activeView, { push: false });
  const visible = filteredTorrents();
  const rendered = renderTorrentRows(visible);
  renderTorrentRowLimit(visible, rendered);
  els.empty.textContent = state.torrents.length === 0 ? "Aucun torrent pour le moment." : "Aucun torrent ne correspond aux filtres.";
  els.empty.hidden = visible.length !== 0;
  els.summary.textContent = visible.length > rendered.length
    ? `${state.renderOffset + 1}–${state.renderOffset + rendered.length} affichés sur ${visible.length} filtrés (${state.torrents.length} au total)`
    : `${visible.length} affiché${visible.length > 1 ? "s" : ""} sur ${state.torrents.length}`;
  renderTrackerStats();
  renderSelection(rendered);
  renderRelinkButton();
  renderSortHeaders();
  updateDetails();
}

function renderTrackerStats() {
  const stats = state.trackerStats || { totals: [], daily: [] };
  const totals = Array.isArray(stats.totals) ? stats.totals : [];
  const daily = Array.isArray(stats.daily) ? stats.daily : [];
  const measured = totals.filter((item) => Number(item.downloaded) > 0 || Number(item.uploaded) > 0);
  els.trackerStatsSummary.textContent = Number(stats.observedDays) > 0
    ? `${measured.length} tracker(s) avec trafic mesuré sur ${stats.observedDays} jour(s) observé(s).`
    : "Premier snapshot enregistré. Les deltas journaliers apparaîtront aux prochaines actualisations.";

  const cards = (totals.length ? totals : [{ tracker: "En attente", downloaded: 0, uploaded: 0, ratio: 0, torrents: state.torrents.length }]).slice(0, 4);
  els.trackerStatsCards.replaceChildren(
    ...cards.map((item) => {
      const article = document.createElement("article");
      article.className = "tracker-stat-card";
      const title = document.createElement("strong");
      title.textContent = item.tracker || "Sans tracker";
      const meta = document.createElement("span");
      meta.textContent = `${Number(item.torrents) || 0} torrent(s) suivis`;
      const metrics = document.createElement("dl");
      for (const [label, value] of [
        ["DL", formatBytes(item.downloaded)],
        ["UL", formatBytes(item.uploaded)],
        ["Ratio", formatRatio(item.ratio)],
      ]) {
        const dt = document.createElement("dt");
        dt.textContent = label;
        const dd = document.createElement("dd");
        dd.textContent = value;
        metrics.append(dt, dd);
      }
      article.append(title, meta, metrics);
      return article;
    }),
  );

  const rows = daily.slice(-12).reverse();
  els.trackerStatsRows.replaceChildren(
    ...rows.map((item) => {
      const tr = document.createElement("tr");
      for (const [label, value] of [
        ["Jour", formatDay(item.date)],
        ["Tracker", item.tracker || "Sans tracker"],
        ["Download", formatBytes(item.downloaded)],
        ["Upload", formatBytes(item.uploaded)],
        ["Ratio", formatRatio(item.ratio)],
      ]) {
        const td = document.createElement("td");
        td.dataset.label = label;
        td.textContent = value;
        if (["Download", "Upload", "Ratio"].includes(label)) td.className = "mono";
        tr.append(td);
      }
      return tr;
    }),
  );
  if (!rows.length) {
    const tr = document.createElement("tr");
    const td = document.createElement("td");
    td.colSpan = 5;
    td.textContent = "Pas encore de delta mesuré. Gardez l'actualisation active pour alimenter les statistiques.";
    tr.append(td);
    els.trackerStatsRows.replaceChildren(tr);
  }
}

function scheduleRender() {
  if (state.renderFrame !== null) return state.renderPromise;
  const token = {};
  let fallbackTimer = null;
  let resolveRender;
  state.renderFrame = token;
  state.renderPromise = new Promise((resolve) => { resolveRender = resolve; });
  const flush = () => {
    if (state.renderFrame !== token) return;
    window.clearTimeout(fallbackTimer);
    state.renderFrame = null;
    try {
      render();
    } finally {
      state.renderPromise = null;
      resolveRender();
    }
  };
  fallbackTimer = window.setTimeout(flush, 32);
  window.requestAnimationFrame?.(flush);
  return state.renderPromise;
}

function stampFreshness(value = new Date()) {
  const observed = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(observed.getTime())) return;
  if (!state.lastUpdatedAt || observed > state.lastUpdatedAt) state.lastUpdatedAt = observed;
  const lastCheck = els.lastCheck;
  if (lastCheck) {
    lastCheck.textContent = formatFreshness(state.lastUpdatedAt);
    lastCheck.setAttribute("datetime", state.lastUpdatedAt.toISOString());
  } else {
    els.refreshStatus.textContent = `À jour ${formatFreshness(state.lastUpdatedAt)}`;
  }
}

function applyDashboardPayload(payload) {
  state.dashboard = {
    alerts: Array.isArray(payload.alerts) ? payload.alerts : [],
    criticalCount: Number(payload.criticalCount) || 0,
    overview: payload.overview && typeof payload.overview === "object" ? payload.overview : {},
    recentActivity: Array.isArray(payload.recentActivity) ? payload.recentActivity : [],
    storage: payload.storage && typeof payload.storage === "object" ? payload.storage : {},
    quickActions: Array.isArray(payload.quickActions) ? payload.quickActions : [],
    services: Array.isArray(payload.services) ? payload.services : [],
    mediaAutomation: payload.mediaAutomation && typeof payload.mediaAutomation === "object"
      ? payload.mediaAutomation
      : { enabled: false, entries: [], notification: null },
  };
  if (state.activeView === "home") scheduleRender();
}

function applyTorrentPayload(payload) {
  const torrents = Array.isArray(payload?.torrents) ? payload.torrents : [];
  const signature = JSON.stringify(torrents);
  if (signature !== state.lastSignature) {
    state.torrents = torrents;
    state.lastSignature = signature;
  }
  stampFreshness(payload?.observedAt || new Date());
  clearError();
  state.backendStatus = torrents.length || state.dashboard.services.length
    ? BACKEND_STATES.ready
    : BACKEND_STATES.empty;
  scheduleRender();
  window.setTimeout(() => tryAutoTr4kerTracker(), 0);
}

function applyStoragePayload(payload) {
  state.storage = payload && typeof payload === "object" ? payload : { disk: {}, rclone: {} };
  const disk = state.storage.disk || {};
  if (Number(disk.usedBytes) > 0) {
    window.DashboardDOM?.updateDiskRing({ percent: disk.usedPercent, usedBytes: disk.usedBytes, totalBytes: disk.totalBytes });
  } else {
    window.DashboardDOM?.hideDiskRing();
  }
}

function applyActivityPayload(payload) {
  const next = payload && typeof payload === "object" ? payload : { summary: {}, timeline: [] };
  if (JSON.stringify(next) === JSON.stringify(state.activity)) return;
  state.activity = next;
  if (state.activeView === "home") scheduleRender();
}

function applyTrackerStatsPayload(payload) {
  if (!payload?.stats || typeof payload.stats !== "object") return;
  if (JSON.stringify(payload.stats) === JSON.stringify(state.trackerStats)) return;
  state.trackerStats = payload.stats;
  if (state.activeView === "torrents") scheduleRender();
}

function applyRelinkStatusPayload(payload) {
  state.relinkStatus = { count: Number(payload?.count) || 0 };
  renderRelinkButton();
}

function liveTopics() {
  return state.activeView === "home"
    ? ["torrents", "dashboard", "storage", "activity", "relink"]
    : ["torrents", "relink"];
}

function applyLiveFrame(frame) {
  if (state.globalActionCount > 0) return;
  if (frame?.type === "freshness") {
    if (frame.sourceUpdatedAt || frame.collectedAt || frame.observedAt) {
      stampFreshness(frame.sourceUpdatedAt || frame.collectedAt || frame.observedAt);
    }
    return;
  }
  const topic = String(frame?.topic || "");
  const payload = frame?.data && typeof frame.data === "object" ? frame.data : {};
  if (frame?.stale && payload.error) {
    state.liveStatus = "stale";
    return;
  }
  const collectedAt = frame?.sourceUpdatedAt || payload.refreshedAt || payload.generatedAt
    || payload.observedAt || payload.source_scanned_at || frame?.collectedAt;
  if (topic === "torrents") applyTorrentPayload({ ...payload, observedAt: collectedAt });
  if (topic === "dashboard") applyDashboardPayload(payload);
  if (topic === "storage") applyStoragePayload(payload);
  if (topic === "activity") applyActivityPayload(payload);
  if (topic === "relink") applyRelinkStatusPayload(payload);
  if (collectedAt) stampFreshness(collectedAt);
}

function applyLiveFrameForRevision(frame, generation, actionRevision) {
  if (generation !== state.liveGeneration || actionRevision !== state.actionRevision || state.globalActionCount > 0) return;
  applyLiveFrame(frame);
}

async function awaitPrimaryRender(primaryRequest) {
  const applied = await primaryRequest;
  if (applied && state.renderPromise) await state.renderPromise;
  return applied;
}

async function pollLiveSections({ signal } = {}) {
  if (state.refreshPromise || state.globalActionCount > 0) return { sections: {} };
  const topics = liveTopics();
  const generation = state.liveGeneration;
  const actionRevision = state.actionRevision;
  const requests = {
    torrents: route("/api/torrents"),
    dashboard: route("/api/dashboard"),
    relink: route("/api/torrents/relink-status"),
    storage: route("/api/storage"),
    activity: route("/api/activity"),
  };
  await Promise.all(topics.map(async (topic) => {
    try {
      const data = await api(requests[topic], { cache: "no-store", retry: false, signal });
      if (signal?.aborted || generation !== state.liveGeneration || actionRevision !== state.actionRevision || state.globalActionCount > 0) return;
      applyLiveFrameForRevision({ type: "snapshot", topic, data }, generation, actionRevision);
    } catch {
      // Une section indisponible ne bloque pas la mise à jour des autres.
    }
  }));
  return { sections: {} };
}

async function submitJob(type, params = {}) {
  return api(route("/api/jobs"), {
    method: "POST",
    body: JSON.stringify({ type, params }),
    retry: false,
  });
}

async function waitForJob(jobId, onUpdate = () => {}) {
  let latest = null;
  while (true) {
    const job = await api(route(`/api/jobs/${encodeURIComponent(jobId)}`), {
      cache: "no-store", retry: false, timeout: 10000,
    });
    latest = job;
    onUpdate(job);
    if (["completed", "failed", "interrupted"].includes(String(job.status || "").toLowerCase())) {
      if (job.status !== "completed") throw new Error(job.error?.message || job.message || "La tâche a échoué.");
      return job;
    }
    await new Promise((resolve) => window.setTimeout(resolve, 1000));
  }
}

function jobProgressLabel(job) {
  const progress = Number(job?.progress);
  const total = Number(job?.total);
  return total > 0 && Number.isFinite(progress)
    ? `${job.message || "Tâche en cours"} (${Math.min(progress, total)}/${total})`
    : job?.message || "Tâche en cours";
}

function startLive() {
  stopLive();
  state.liveActionRevision = state.actionRevision;
  if (!state.prefs.autoRefresh || document.hidden || typeof window.DashboardLive?.createLiveSubscription !== "function") return;
  const topics = liveTopics();
  const generation = state.liveGeneration;
  const actionRevision = state.actionRevision;
  const dispatchFrame = (frame) => applyLiveFrameForRevision(frame, generation, actionRevision);
  state.liveSubscription = window.DashboardLive.createLiveSubscription({
    streamUrl: `${route("/api/events")}?topics=${encodeURIComponent(topics.join(","))}`,
    pollIntervalMs: 1000,
    reconnectDelayMs: 2500,
    poll: pollLiveSections,
    handlers: {
      snapshot: dispatchFrame,
      section: dispatchFrame,
      freshness: dispatchFrame,
      job(frame) {
        const job = frame?.job || {};
        if (state.organizeRunning && (job.type || job.metadata?.type) === "library-apply") renderOrganizeProgressJob(job);
        if (job.status === "running" || job.status === "queued") els.refreshStatus.textContent = jobProgressLabel(job);
      },
      status(value) {
        if (generation !== state.liveGeneration) return;
        state.liveStatus = value?.mode || "idle";
        restartRefreshTimer();
      },
      error() {
        state.liveStatus = "degraded";
      },
    },
  });
  state.liveSubscription.start();
}

function stopLive() {
  state.liveGeneration += 1;
  const subscription = state.liveSubscription;
  state.liveSubscription = null;
  subscription?.stop();
  state.liveStatus = "idle";
}

function resumeLiveAfterAction() {
  if (state.globalActionCount === 0 && state.liveActionRevision !== state.actionRevision) startLive();
}

async function loadDashboard() {
  const payload = await api(route("/api/dashboard"), { cache: "no-store" });
  applyDashboardPayload(payload);
  scheduleRender();
}

async function loadTorrents({ silent = false, force = false } = {}) {
  if (!force && (state.globalActionCount > 0 || document.hidden)) return null;
  if (force && state.globalActionCount > 0) {
    state.forceRefreshQueued = true;
    return null;
  }
  if (state.liveSubscription && state.liveStatus === "polling") {
    state.resumeLiveAfterRefresh = true;
    stopLive();
  }
  if (state.refreshPromise) {
    if (force && state.refreshRevision !== state.actionRevision) state.forceRefreshQueued = true;
    const activeRefresh = state.refreshPromise;
    return activeRefresh.then((result) => {
      if (!force || !state.forceRefreshQueued || document.hidden || state.globalActionCount > 0) return result;
      state.forceRefreshQueued = false;
      return loadTorrents({ silent: true, force: true });
    });
  }
  if (force) state.forceRefreshQueued = false;
  if (!silent) {
    els.refreshStatus.textContent = "Actualisation...";
    if (!state.lastUpdatedAt) {
      state.backendStatus = BACKEND_STATES.loading;
      if (state.activeView === "home") renderHome();
    }
  }

  const revisionAtStart = state.actionRevision;
  state.refreshRevision = revisionAtStart;
  const request = (async () => {
    const cycle = state.pollCycle++;
    const refreshActivity = force || cycle % 3 === 0;
    const refreshStorage = force || cycle % 7 === 0;
    const refreshTrackers = force || cycle % 30 === 0;
    const requests = [
      [route("/api/torrents"), applyTorrentPayload],
      [route("/api/dashboard"), applyDashboardPayload],
      [route("/api/torrents/relink-status"), applyRelinkStatusPayload],
    ];
    if (refreshStorage) requests.push([route("/api/storage"), applyStoragePayload]);
    if (refreshActivity) requests.push([route("/api/activity"), applyActivityPayload]);
    if (refreshTrackers) requests.push([route("/api/torrents/stats/trackers"), applyTrackerStatsPayload]);

    const fetchAndApply = async ([path, apply]) => {
      const payload = await api(path, { cache: "no-store" });
      if (revisionAtStart !== state.actionRevision || state.globalActionCount > 0) return false;
      apply(payload);
      return true;
    };
    const primaryRequest = fetchAndApply(requests[0]);
    if (!state.secondaryRefreshPromise) {
      const secondaryRequests = requests.slice(1).map((entry) => fetchAndApply(entry));
      state.secondaryRefreshPromise = Promise.allSettled(secondaryRequests).then((results) => {
        const failures = results.filter((result) => result.status === "rejected");
        state.secondaryRefreshError = failures.length === secondaryRequests.length && failures.length
          ? failures[0].reason
          : null;
      }).finally(() => { state.secondaryRefreshPromise = null; });
    }
    try {
      const applied = await awaitPrimaryRender(primaryRequest);
      state.primaryRefreshResolved = true;
      if (applied && revisionAtStart === state.actionRevision && state.globalActionCount === 0
          && (state.liveActionRevision !== state.actionRevision || state.resumeLiveAfterRefresh)) {
        state.resumeLiveAfterRefresh = false;
        startLive();
      }
    } catch (error) {
      if (revisionAtStart === state.actionRevision) {
        state.backendStatus = state.lastUpdatedAt ? BACKEND_STATES.degraded : BACKEND_STATES.unavailable;
        if (state.activeView === "home") renderHome();
        showError(error);
        if (!state.lastUpdatedAt) els.refreshStatus.textContent = "Erreur";
      }
    }
  })();
  state.refreshPromise = request.finally(() => {
    state.refreshPromise = null;
    state.refreshRevision = null;
  });
  return state.refreshPromise;
}

async function loadTrackerIndex() {
  try {
    const payload = await api(route("/api/trackers/index"), { cache: "no-store" });
    if (payload && typeof payload.index === "object" && typeof payload.domains === "object") {
      state.trackerIndex = { index: payload.index, domains: payload.domains };
      if (state.activeView === "torrents") render();
    }
  } catch {
    // Tracker index unavailable - filter will be empty
  }
}

function actionText(action) {
  return {
    pause: "Mise en pause…",
    resume: "Reprise…",
    "force-start": "Mise à jour du partage forcé…",
    delete: "Suppression…",
    add: "Ajout…",
  }[action] || "Action…";
}

function beginGlobalAction() {
  state.globalActionCount += 1;
}

function endGlobalAction() {
  state.globalActionCount = Math.max(0, state.globalActionCount - 1);
  if (state.globalActionCount > 0) return;
  state.forceRefreshQueued = true;
  if (document.hidden) return;
  window.setTimeout(() => {
    if (state.globalActionCount > 0 || !state.forceRefreshQueued || document.hidden) return;
    loadTorrents({ silent: true, force: true });
  }, 0);
}

async function runTorrentAction(hashes, action, options = {}) {
  state.actionRevision += 1;
  const busy = actionText(action);
  hashes.forEach((hash) => {
    state.rowBusy.set(hash, busy);
    state.rowErrors.delete(hash);
  });
  beginGlobalAction();
  render();
  try {
    await api(route(`/api/torrents/${action}`), {
      method: "POST",
      body: JSON.stringify({ hashes, ...options }),
    });
    if (action === "pause") {
      showUndoToast(
        hashes.length > 1 ? `${hashes.length} torrents mis en pause.` : "Torrent mis en pause.",
        "Annuler",
        () => runTorrentAction(hashes, "resume"),
      );
    } else {
      showToast(
        action === "resume"
          ? "Torrent repris."
          : action === "force-start"
            ? (options.enabled ? "Partage forcé activé." : "Partage forcé désactivé.")
            : "Torrent supprimé.",
      );
    }
    if (action === "delete") hashes.forEach((hash) => state.selected.delete(hash));
    await loadTorrents({ silent: true, force: true });
  } catch (error) {
    hashes.forEach((hash) => state.rowErrors.set(hash, describeError(error)));
    render();
  } finally {
    hashes.forEach((hash) => state.rowBusy.delete(hash));
    endGlobalAction();
    render();
  }
}

function openDeleteDialog(torrents, trigger) {
  if (!torrents.length) {
    showToast("Aucun torrent sélectionné.");
    return;
  }
  state.lastFocus = trigger || document.activeElement;
  state.pendingDelete = torrents;
  els.deleteTitle.textContent = torrents.length > 1 ? "Supprimer les torrents" : "Supprimer le torrent";
  els.deleteTorrentName.textContent = torrents.length > 1 ? `${torrents.length} torrents sélectionnés` : torrents[0]?.name || "";
  els.deleteForm.deleteMode.value = "torrent";
  els.confirmText.value = "";
  updateDeleteConfirm();
  if (typeof trapFocus === "function") trapFocus(els.deleteDialog);
  els.deleteDialog.showModal();
}

function updateDeleteConfirm() {
  const withFiles = els.deleteForm.deleteMode.value === "files";
  els.strongConfirm.hidden = !withFiles;
  els.confirmDeleteButton.disabled = withFiles && els.confirmText.value.trim() !== "SUPPRIMER";
}

async function confirmDelete() {
  const torrents = state.pendingDelete || [];
  if (!torrents.length) return;
  const deleteFiles = els.deleteForm.deleteMode.value === "files";
  if (deleteFiles && els.confirmText.value.trim() !== "SUPPRIMER") {
    els.confirmText.focus();
    return;
  }
  els.confirmDeleteButton.disabled = true;
  els.cancelDeleteButton.disabled = true;
  els.confirmDeleteButton.textContent = "Suppression…";
  els.deleteDialog.close();
  try {
    await runTorrentAction(torrents.map((torrent) => torrent.hash), "delete", { deleteFiles });
    state.pendingDelete = null;
  } finally {
    els.confirmDeleteButton.disabled = false;
    els.cancelDeleteButton.disabled = false;
    els.confirmDeleteButton.textContent = "Supprimer";
  }
}

function detailRows(torrent) {
  const meta = stateMeta(torrent);
  return [
    ["Nom complet", torrent.name],
    ["Hash", torrent.hash],
    ["État", meta.text],
    ["Progression", formatPercent(torrent.progress)],
    ["Téléchargé", formatBytes(torrent.downloaded)],
    ["Restant", formatBytes(torrent.remaining)],
    ["Descendant", formatSpeed(torrent.downloadSpeed)],
    ["Montant", formatSpeed(torrent.uploadSpeed)],
    ["ETA", formatEta(torrent.eta)],
    ["Ratio", formatRatio(torrent.ratio)],
    ["Seeders", Number(torrent.seeders) || 0],
    ["Leechers", Number(torrent.leechers) || 0],
    ["Disponibilité", formatRatio(torrent.availability)],
    ["Catégorie", torrent.category || "—"],
    ["Tags", torrent.tags || "—"],
    ["Limite DL", Number(torrent.downloadLimit) > 0 ? formatSpeed(torrent.downloadLimit) : "Illimitée"],
    ["Limite UL", Number(torrent.uploadLimit) > 0 ? formatSpeed(torrent.uploadLimit) : "Illimitée"],
    ["Séquentiel", torrent.sequentialDownload ? "Activé" : "Désactivé"],
    ["Chemin", torrent.savePath || "—"],
    ["Ajout", formatDate(torrent.addedOn)],
    ["Fin", formatDate(torrent.completionOn)],
  ];
}

async function runAdvancedAction(hash, action, payload = {}, successMessage = "Action appliquée.") {
  state.actionRevision += 1;
  beginGlobalAction();
  try {
    await api(route(`/api/torrents/${action}`), {
      method: "POST",
      body: JSON.stringify({ hashes: [hash], ...payload }),
    });
    showToast(successMessage);
    await loadTorrents({ silent: true, force: true });
  } catch (error) {
    showError(error);
  } finally {
    endGlobalAction();
  }
}

function openDetails(hash, trigger) {
  state.detailHash = hash;
  state.lastFocus = trigger || document.activeElement;
  updateDetails();
  if (typeof trapFocus === "function") trapFocus(els.detailDialog);
  els.detailDialog.showModal();
}

function updateDetails() {
  if (!state.detailHash) return;
  const torrent = state.torrents.find((item) => item.hash === state.detailHash);
  if (!torrent) {
    els.detailDialog.close();
    return;
  }
  els.detailTitle.textContent = torrent.name;
  const dl = document.createElement("dl");
  for (const [label, value] of detailRows(torrent)) {
    const dt = document.createElement("dt");
    dt.textContent = label;
    const dd = document.createElement("dd");
    if (label === "Hash") {
      const code = document.createElement("code");
      code.textContent = value;
      const copy = button("Copier", "secondary", async () => {
        await navigator.clipboard?.writeText(value);
        showToast("Hash copié.");
      });
      dd.append(code, copy);
    } else {
      dd.textContent = value;
    }
    dl.append(dt, dd);
  }
  const advanced = document.createElement("section");
  advanced.className = "detail-advanced";
  const title = document.createElement("h3");
  title.textContent = "Plus";
  const actions = document.createElement("div");
  actions.className = "action-row";
  actions.append(
    ...(["missingFiles", "error", "pausedDL", "stoppedDL"].includes(torrent.state)
      ? [button("Réparer l'emplacement", "primary", () => openRelinkDialog([torrent.hash]))]
      : []),
    ...(isComplete(torrent)
      ? [button("Ranger ce torrent", "primary", () => openOrganizeMediaDialog([torrent.hash], document.activeElement))]
      : []),
    button("Revérifier", "secondary", () => runAdvancedAction(torrent.hash, "recheck", {}, "Revérification demandée.")),
    button("Nouvelle annonce", "secondary", () => runAdvancedAction(torrent.hash, "reannounce", {}, "Nouvelle annonce demandée.")),
    button(
      torrent.sequentialDownload ? "Séquentiel normal" : "Téléchargement séquentiel",
      torrent.sequentialDownload ? "primary" : "secondary",
      () => runAdvancedAction(
        torrent.hash,
        "set-sequential",
        { enabled: !torrent.sequentialDownload },
        torrent.sequentialDownload ? "Téléchargement séquentiel désactivé." : "Téléchargement séquentiel activé.",
      ),
    ),
  );

  const form = document.createElement("form");
  form.className = "advanced-form";
  const formField = (labelText, name, value, type = "text") => {
    const label = document.createElement("label");
    label.append(document.createTextNode(labelText));
    const input = document.createElement("input");
    input.name = name;
    input.type = type;
    input.value = String(value);
    if (type === "number") input.min = "0";
    label.append(input);
    return label;
  };
  form.append(
    formField("Catégorie", "category", torrent.category || ""),
    formField("Tags", "tags", torrent.tags || ""),
    formField("Limite DL (KiB/s)", "downloadLimit", Math.max(0, Math.floor((Number(torrent.downloadLimit) || 0) / 1024)), "number"),
    formField("Limite UL (KiB/s)", "uploadLimit", Math.max(0, Math.floor((Number(torrent.uploadLimit) || 0) / 1024)), "number"),
  );
  const submit = document.createElement("button");
  submit.type = "submit";
  submit.className = "button primary";
  submit.textContent = "Appliquer";
  form.append(submit);
  form.addEventListener("submit", async (event) => {
    event.preventDefault();
    const data = new FormData(form);
    await runAdvancedAction(torrent.hash, "set-category", { category: String(data.get("category") || "") }, "Catégorie mise à jour.");
    if (String(data.get("tags") || "").trim()) {
      await runAdvancedAction(torrent.hash, "add-tags", { tags: String(data.get("tags") || "") }, "Tags mis à jour.");
    }
    await runAdvancedAction(
      torrent.hash,
      "set-download-limit",
      { limitKiB: Math.max(0, Number(data.get("downloadLimit") || 0)) },
      "Limite de téléchargement mise à jour.",
    );
    await runAdvancedAction(
      torrent.hash,
      "set-upload-limit",
      { limitKiB: Math.max(0, Number(data.get("uploadLimit") || 0)) },
      "Limite d'envoi mise à jour.",
    );
  });
  advanced.append(title, actions, form);

  const trackerSection = document.createElement("section");
  trackerSection.className = "detail-advanced";
  const tTitle = document.createElement("h3");
  tTitle.textContent = "Trackers";
  const tBody = document.createElement("div");
  tBody.className = "tracker-list";
  tBody.textContent = "Chargement…";
  trackerSection.append(tTitle, tBody);

  els.detailBody.replaceChildren(dl, trackerSection, advanced);

  const currentHash = torrent.hash;
  api(route(`/api/torrents/${currentHash}/trackers`), { cache: "no-store" }).then((data) => {
    if (state.detailHash !== currentHash) return;
    const trackers = Array.isArray(data.trackers) ? data.trackers : [];
    const filtered = trackers.filter((tr) => {
      const url = String(tr.url || "");
      return !url.startsWith("** [DHT]") && !url.startsWith("** [PeX]") && !url.startsWith("** [LSD]") && !url.startsWith("** [Metadata]");
    });
    if (!filtered.length) {
      tBody.textContent = "Aucun tracker.";
      return;
    }
    const list = document.createElement("div");
    list.className = "tracker-grid";
    for (const tr of filtered) {
      const row = document.createElement("div");
      row.className = "tracker-row";
      const statusClass = ["disabled", "not_contacted", "working", "updating", "not_working"][Number(tr.status)] || "unknown";
      const statusLabels = { disabled: "Désactivé", not_contacted: "En attente", working: "Opérationnel", updating: "Mise à jour", not_working: "Erreur", unknown: "Inconnu" };
      const url = document.createElement("div");
      url.className = "tracker-url";
      url.textContent = String(tr.url || "—");
      const meta = document.createElement("div");
      meta.className = "tracker-meta";
      const trackerStatus = document.createElement("span");
      trackerStatus.className = `tracker-status tracker-status-${statusClass}`;
      trackerStatus.textContent = statusLabels[statusClass] || "Inconnu";
      meta.append(trackerStatus);
      if (Number(tr.num_seeds) > 0) {
        const seeds = document.createElement("span");
        seeds.textContent = `${Number(tr.num_seeds)} S`;
        meta.append(seeds);
      }
      if (Number(tr.num_leeches) > 0) {
        const leeches = document.createElement("span");
        leeches.textContent = `${Number(tr.num_leeches)} L`;
        meta.append(leeches);
      }
      if (tr.msg) {
        const message = document.createElement("span");
        message.className = "tracker-msg";
        message.textContent = String(tr.msg);
        meta.append(message);
      }
      row.append(url, meta);
      list.append(row);
    }
    tBody.replaceChildren(list);
  }).catch(() => {
    tBody.textContent = "Erreur de chargement.";
  });
}

function openAddTrackerDialog() {
  const selectedHashes = [...state.selected];
  if (!selectedHashes.length) {
    showToast("Aucun torrent sélectionné.");
    return;
  }
  state.lastFocus = document.activeElement;
  const visible = filteredTorrents();
  const count = selectedHashes.filter((h) => visible.some((t) => t.hash === h)).length;
  els.addTrackerTitle.textContent = "Ajouter un tracker";
  els.addTrackerCount.textContent = `Ajouter un tracker à ${selectedHashes.length} torrent${selectedHashes.length > 1 ? "s" : ""}${count !== selectedHashes.length ? ` (dont ${count} dans les résultats affichés)` : ""}`;
  els.addTrackerUrlInput.value = "";
  els.addTrackerMessage.textContent = "";
  els.confirmAddTrackerButton.disabled = false;
  els.confirmAddTrackerButton.textContent = `Ajouter aux ${selectedHashes.length} torrent${selectedHashes.length > 1 ? "s" : ""}`;
  if (typeof trapFocus === "function") trapFocus(els.addTrackerDialog);
  els.addTrackerDialog.showModal();
}

async function confirmAddTracker() {
  const selectedHashes = [...state.selected];
  if (!selectedHashes.length) return;
  const trackerUrl = els.addTrackerUrlInput.value.trim();
  if (!trackerUrl) {
    els.addTrackerMessage.textContent = "Entrez une adresse de tracker.";
    els.addTrackerUrlInput.focus();
    return;
  }
  els.confirmAddTrackerButton.disabled = true;
  els.confirmAddTrackerButton.textContent = "Ajout…";
  els.addTrackerMessage.textContent = "";
  try {
    state.actionRevision += 1;
    const payload = await api(route("/api/torrents/add-tracker"), {
      method: "POST",
      body: JSON.stringify({ hashes: selectedHashes, trackerUrl }),
    });
    const parts = [];
    if (payload.updated) parts.push(`${payload.updated} configuré${payload.updated > 1 ? "s" : ""}`);
    if (payload.duplicates) parts.push(`${payload.duplicates} déjà présent${payload.duplicates > 1 ? "s" : ""}`);
    if (payload.missing) parts.push(`${payload.missing} introuvable${payload.missing > 1 ? "s" : ""}`);
    if (payload.failed) parts.push(`${payload.failed} échec${payload.failed > 1 ? "s" : ""}`);
    showToast(`Tracker configuré sur ${payload.updated} torrent${payload.updated > 1 ? "s" : ""}${parts.length ? ` (${parts.join(", ")})` : ""}.`);
    els.addTrackerDialog.close();
    await loadTorrents({ silent: true, force: true });
    loadTrackerIndex();
  } catch (error) {
    els.addTrackerMessage.textContent = describeError(error);
  } finally {
    els.confirmAddTrackerButton.disabled = false;
    els.confirmAddTrackerButton.textContent = "Ajouter";
    resumeLiveAfterAction();
  }
}

async function addConfiguredTrackerToHashes(hashes, endpoint, successLabel) {
  if (!hashes.length) {
    showToast("Aucun torrent sélectionné.");
    return;
  }
  try {
    state.actionRevision += 1;
    const payload = await api(route(endpoint), {
      method: "POST",
      body: JSON.stringify({ hashes }),
    });
    const parts = [];
    if (payload.updated) parts.push(`${payload.updated} configuré${payload.updated > 1 ? "s" : ""}`);
    if (payload.duplicates) parts.push(`${payload.duplicates} déjà présent${payload.duplicates > 1 ? "s" : ""}`);
    if (payload.missing) parts.push(`${payload.missing} introuvable${payload.missing > 1 ? "s" : ""}`);
    if (payload.failed) parts.push(`${payload.failed} échec${payload.failed > 1 ? "s" : ""}`);
    showToast(`${successLabel} sur ${payload.updated} torrent${payload.updated > 1 ? "s" : ""}${parts.length ? ` (${parts.join(", ")})` : ""}.`);
    await loadTorrents({ silent: true, force: true });
    loadTrackerIndex();
  } catch (error) {
    showToast(describeError(error));
  } finally {
    resumeLiveAfterAction();
  }
}

async function addConfiguredTracker(endpoint, successLabel) {
  await addConfiguredTrackerToHashes([...state.selected], endpoint, successLabel);
}

async function tryAutoTr4kerTracker() {
  if (state.autoTr4kerAttempted || state.sourceHint !== "tr4ker" || !state.pendingReleaseTitle) return;
  const visibleHashes = filteredTorrents().map((torrent) => torrent.hash);
  if (!visibleHashes.length) return;
  state.autoTr4kerAttempted = true;
  await addConfiguredTrackerToHashes(visibleHashes, "/api/torrents/add-tr4ker-tracker", "Tracker tr4ker configuré automatiquement");
}

function cancelAddTracker() {
  els.addTrackerDialog.close();
}

function renderRelinkButton() {
  if (!els.relinkMissingButton) return;
  const count = Number(state.relinkStatus?.count) || 0;
  els.relinkMissingButton.hidden = count === 0;
  els.relinkMissingButton.textContent = count ? `Réparer les fichiers manquants (${count})` : "Réparer les fichiers manquants";
}

function relinkPlanForMode(plan, mode) {
  const category = mode === "category";
  return {
    groups: (category ? plan?.relinkCategory : plan?.relink) || [],
    recheck: (category ? plan?.recheckOnlyCategory : plan?.recheckOnly) || [],
  };
}

function renderRelinkPlan() {
  if (!els.relinkPlan) return;
  const plan = state.relinkPlan || {};
  const mode = state.relinkMode === "in_place" ? "in_place" : "category";
  const selection = relinkPlanForMode(plan, mode);
  const count = selection.groups.reduce((total, group) => total + (group.hashes?.length || 0), 0);
  const recheckCount = selection.recheck.length;
  const skipped = Number(plan.skippedCount) || 0;
  const fallback = mode === "category" ? Number(plan.categoryFallbackCount) || 0 : 0;
  const summaryParts = [
    `${count} torrent${count > 1 ? "s" : ""} ${mode === "category" ? "à réparer et classer" : "à réaligner"}`,
  ];
  if (recheckCount) summaryParts.push(`${recheckCount} déjà aligné${recheckCount > 1 ? "s" : ""}`);
  if (fallback) summaryParts.push(`${fallback} sans classement`);
  if (skipped) summaryParts.push(`${skipped} ignoré${skipped > 1 ? "s" : ""}`);
  if (els.relinkSummary) els.relinkSummary.textContent = `${summaryParts.join(" · ")}.`;
  if (els.relinkModeNote) {
    els.relinkModeNote.textContent = mode === "category"
      ? "Le contenu est déplacé vers Jeux, Films, Séries ou Livres en une seule opération, puis revérifié."
      : "qBittorrent est seulement pointé vers l’emplacement réel du contenu : aucun fichier n’est déplacé.";
  }
  els.relinkPlan.replaceChildren();
  const list = document.createElement("ul");
  const maxRows = 100;
  let renderedRows = 0;
  let totalRows = count + recheckCount;
  selection.groups.forEach((group) => {
    (group.entries || []).forEach((entry) => {
      if (renderedRows >= maxRows) return;
      renderedRows += 1;
      const item = document.createElement("li");
      const title = document.createElement("strong");
      title.textContent = entry.name;
      const detail = document.createElement("span");
      detail.className = "organize-plan-detail";
      const fallbackNote = mode === "category" && entry.categoryApplied === false
        ? ` · classement indisponible (${entry.categoryReason || "repli"})`
        : "";
      const layoutLabel = group.layout === "NoSubfolder" ? "fichiers à plat" : "sous-dossier";
      detail.textContent = `${group.location} · ${layoutLabel}${fallbackNote}`;
      item.append(title, detail);
      list.append(item);
    });
  });
  selection.recheck.forEach((entry) => {
    if (renderedRows >= maxRows) return;
    renderedRows += 1;
    const item = document.createElement("li");
    item.textContent = `${entry.name} — déjà aligné, revérification demandée`;
    list.append(item);
  });
  if (list.childElementCount) els.relinkPlan.append(list);
  if (totalRows > renderedRows) {
    const more = document.createElement("p");
    more.className = "field-message";
    more.textContent = `${totalRows - renderedRows} torrent(s) supplémentaire(s) seront traités avec la sélection.`;
    els.relinkPlan.append(more);
  }
  if (!list.childElementCount) {
    const empty = document.createElement("p");
    empty.className = "field-message";
    empty.textContent = "Aucun torrent à réparer avec ce mode.";
    els.relinkPlan.append(empty);
  }
  if (els.confirmRelinkButton) els.confirmRelinkButton.disabled = count + recheckCount === 0;
}

function setRelinkMode(mode) {
  state.relinkMode = mode === "in_place" ? "in_place" : "category";
  renderRelinkPlan();
}

async function runRelink(hashes = [], mode = state.relinkMode) {
  try {
    state.actionRevision += 1;
    const params = {
      mode: mode === "in_place" ? "in_place" : "category",
      recheck: true,
    };
    if (Array.isArray(hashes) && hashes.length) params.hashes = hashes;
    const submitted = await submitJob("relink", params);
    els.refreshStatus.textContent = "Réparation en arrière-plan…";
    const job = await waitForJob(submitted.id, (value) => { els.refreshStatus.textContent = jobProgressLabel(value); });
    const payload = job.result || {};
    const result = payload.result;
    if (!result || (!result.relinked && !result.rechecked)) {
      showToast("Aucun torrent n'a pu être repositionné.");
      return false;
    }
    const parts = [];
    if (result.relinked) parts.push(`${result.relinked} repositionné${result.relinked > 1 ? "s" : ""}`);
    if (result.mode === "category" && result.relinked) parts.push("classé(s)");
    if (result.paused) parts.push(`${result.paused} mis en pause`);
    if (result.rechecked) parts.push(`${result.rechecked} revérifié${result.rechecked > 1 ? "s" : ""}`);
    if (result.failed) parts.push(`${result.failed} échec${result.failed > 1 ? "s" : ""}`);
    if (result.skipped) parts.push(`${result.skipped} ignoré${result.skipped > 1 ? "s" : ""}`);
    showToast(`Réparation : ${parts.join(", ")}. Vérifiez avant de reprendre.`);
    state.relinkPlan = null;
    await loadTorrents({ silent: true, force: true });
    return true;
  } catch (error) {
    showToast(describeError(error));
    resumeLiveAfterAction();
    return false;
  }
}

async function openRelinkDialog(hashes = []) {
  state.relinkHashes = Array.isArray(hashes) ? [...hashes] : [];
  state.relinkMode = "category";
  state.relinkPlan = null;
  els.relinkMessage.textContent = "";
  els.relinkSummary.textContent = "Analyse des fichiers à réparer…";
  els.relinkPlan.replaceChildren();
  els.confirmRelinkButton.disabled = true;
  els.confirmRelinkButton.textContent = "Réparer";
  if (typeof trapFocus === "function") trapFocus(els.relinkDialog);
  if (!els.relinkDialog.open) els.relinkDialog.showModal();
  if (els.relinkModeNote) {
    els.relinkModeNote.textContent = "Le contenu est déplacé vers Jeux, Films, Séries ou Livres en une seule opération, puis revérifié.";
  }
  document.querySelectorAll('input[name="relinkMode"]').forEach((input) => {
    input.checked = input.value === "category";
  });
  try {
    const params = state.relinkHashes.length ? { hashes: state.relinkHashes } : {};
    const submitted = await submitJob("relink-preview", params);
    const job = await waitForJob(submitted.id, (value) => {
      els.relinkSummary.textContent = jobProgressLabel(value);
      els.refreshStatus.textContent = jobProgressLabel(value);
    });
    const payload = job.result || {};
    state.relinkPlan = payload.plan || {};
    renderRelinkPlan();
    if (!els.relinkDialog.open) els.relinkDialog.showModal();
  } catch (error) {
    els.relinkSummary.textContent = describeError(error);
    els.relinkPlan.replaceChildren();
    els.confirmRelinkButton.disabled = true;
    if (!els.relinkDialog.open) els.relinkDialog.showModal();
  }
}

async function confirmRelink() {
  els.confirmRelinkButton.disabled = true;
  els.confirmRelinkButton.textContent = "Réparation…";
  els.relinkMessage.textContent = "";
  els.relinkDialog.close();
  try {
    const ok = await runRelink(state.relinkHashes, state.relinkMode);
    if (!ok) showToast(els.relinkMessage.textContent || "La réparation a échoué.");
  } catch (error) {
    els.relinkMessage.textContent = describeError(error);
  } finally {
    els.confirmRelinkButton.disabled = false;
    els.confirmRelinkButton.textContent = "Réparer";
  }
}

function cancelRelink() {
  state.relinkHashes = [];
  state.relinkPlan = null;
  els.relinkDialog.close();
}

async function openOrganizeMediaDialog(hashes = [], trigger = null) {
  if (state.organizeRunning) {
    showToast("Un rangement est déjà en cours. Sa progression reste visible dans la barre d’état.");
    return;
  }
  state.organizeHashes = Array.isArray(hashes) ? hashes : [];
  state.organizeRunId = "";
  state.organizeSelected = new Set();
  state.organizeOrphanSelected = new Set();
  state.organizeDuplicateSelected = new Set();
  state.organizeFilter = "all";
  state.lastFocus = trigger || document.activeElement;
  resetOrganizeWorkflow();
  els.organizeMediaMessage.textContent = "";
  els.organizeMediaSummary.textContent = "Analyse des torrents terminés…";
  els.organizeMediaPlan.replaceChildren();
  els.confirmOrganizeMediaButton.disabled = true;
  if (typeof trapFocus === "function") trapFocus(els.organizeMediaDialog);
  if (!els.organizeMediaDialog.open) els.organizeMediaDialog.showModal();
  try {
    const refreshJob = await submitJob("library-refresh");
    await waitForJob(refreshJob.id, (job) => {
      els.organizeMediaSummary.textContent = jobProgressLabel(job);
      els.refreshStatus.textContent = jobProgressLabel(job);
    });
    const previewJob = await submitJob("library-preview", state.organizeHashes.length ? { hashes: state.organizeHashes } : {});
    const completedPreview = await waitForJob(previewJob.id, (job) => {
      els.organizeMediaSummary.textContent = jobProgressLabel(job);
      els.refreshStatus.textContent = jobProgressLabel(job);
    });
    const payload = completedPreview.result || {};
    state.organizeRunId = payload.runId || "";
    const plan = payload.plan || {};
    const entries = plan.entries || [];
    const orphanMedia = plan.orphanMedia || [];
    const duplicateGroups = plan.duplicateGroups || [];
    state.organizePlanEntries = entries;
    state.organizePlanOrphans = orphanMedia;
    state.organizePlanDuplicates = duplicateGroups;
    entries.forEach((entry) => state.organizeSelected.add(entry.hash));
    orphanMedia.forEach((item) => state.organizeOrphanSelected.add(item.path));
    duplicateGroups.filter((group) => group.status !== "conflict").forEach((group) => state.organizeDuplicateSelected.add(group.id));
    if (els.organizeSelectAll) els.organizeSelectAll.checked = entries.length + orphanMedia.length > 0;
    const warnings = plan.warnings || [];
    els.organizeMediaSummary.textContent = `${entries.length} torrent${entries.length > 1 ? "s" : ""} à ranger · ${warnings.length} avertissement${warnings.length > 1 ? "s" : ""}.`;
    const list = document.createElement("ul");
    entries.forEach((entry) => {
      const item = document.createElement("li");
      item.dataset.kind = entry.kind || "warning";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.checked = true;
      checkbox.dataset.hash = entry.hash;
      checkbox.setAttribute("aria-label", `Sélectionner ${entry.name}`);
      checkbox.addEventListener("change", () => {
        if (checkbox.checked) state.organizeSelected.add(entry.hash);
        else state.organizeSelected.delete(entry.hash);
        renderOrganizeSelection();
      });
      const title = document.createElement("strong");
      title.textContent = entry.name;
      const detail = document.createElement("span");
      detail.className = "organize-plan-detail";
      detail.textContent = `${ORGANIZE_KIND_LABELS[entry.kind] || "Média"} · ${entry.hash.slice(0, 8)} · ${entry.fileCount} fichier${entry.fileCount > 1 ? "s" : ""} · ${entry.layout}`;
      const path = document.createElement("div");
      path.className = "organize-route";
      const [sourcePath, destinationPath] = [entry.currentPath || "Emplacement non renseigné", entry.targetPath];
      const source = document.createElement("span");
      source.className = "organize-route-place organize-route-source";
      source.textContent = sourcePath;
      const arrow = document.createElement("span");
      arrow.className = "organize-route-arrow";
      arrow.setAttribute("aria-hidden", "true");
      arrow.textContent = "→";
      const destination = document.createElement("span");
      destination.className = "organize-route-place organize-route-destination";
      destination.textContent = destinationPath;
      path.append(source, arrow, destination);
      item.append(checkbox, title, detail, path);
      if (entry.operations?.length) {
        const operations = document.createElement("details");
        operations.className = "organize-operations";
        const summary = document.createElement("summary");
        summary.textContent = `${entry.operations.length} chemin${entry.operations.length > 1 ? "s" : ""} à adapter`;
        const operationList = document.createElement("ul");
        entry.operations.forEach((operation) => {
          const operationItem = document.createElement("li");
          operationItem.textContent = `${operation.type === "folder" ? "Dossier" : "Fichier"} : ${operation.oldPath} → ${operation.newPath}`;
          operationList.append(operationItem);
        });
        operations.append(summary, operationList);
        item.append(operations);
      }
      list.append(item);
    });
    orphanMedia.forEach((orphan) => {
      const item = document.createElement("li");
      item.dataset.kind = "orphan";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.checked = true;
      checkbox.dataset.orphanPath = orphan.path;
      checkbox.setAttribute("aria-label", `Sélectionner le média orphelin ${orphan.path}`);
      checkbox.addEventListener("change", () => {
        if (checkbox.checked) state.organizeOrphanSelected.add(orphan.path);
        else state.organizeOrphanSelected.delete(orphan.path);
        renderOrganizeSelection();
      });
      const title = document.createElement("strong");
      title.textContent = orphan.path;
      const detail = document.createElement("span");
      detail.className = "organize-plan-detail";
      detail.textContent = "Média orphelin · aucun torrent associé · validation manuelle requise";
      item.append(checkbox, title, detail);
      list.append(item);
    });
    duplicateGroups.forEach((group) => {
      const item = document.createElement("li");
      item.dataset.kind = "duplicate";
      const checkbox = document.createElement("input");
      checkbox.type = "checkbox";
      checkbox.checked = group.status !== "conflict";
      checkbox.disabled = group.status === "conflict";
      checkbox.dataset.duplicateId = group.id;
      checkbox.setAttribute("aria-label", `Sélectionner la fusion ${group.canonicalPath}`);
      checkbox.addEventListener("change", () => {
        if (checkbox.checked) state.organizeDuplicateSelected.add(group.id);
        else state.organizeDuplicateSelected.delete(group.id);
        renderOrganizeSelection();
      });
      const title = document.createElement("strong");
      title.textContent = `Dossier en doublon · ${group.canonicalPath}`;
      const detail = document.createElement("span");
      detail.className = "organize-plan-detail";
      const groupStatus = group.status === "ready"
        ? ((group.associatedTorrents || []).length ? "Prêt à fusionner" : "Torrent introuvable — fusion orpheline")
        : group.status === "verification_required" ? "Contenu probable — vérification au moment de l’application" : "Conflit — validation requise";
      detail.textContent = `${groupStatus} · ${group.exactFiles} identique(s) · ${group.complementaryFiles} complémentaire(s) · ${group.recoverableBytes} o récupérables`;
      const path = document.createElement("span");
      path.className = "organize-plan-path";
      path.textContent = `Sources : ${(group.sourcePaths || []).join(", ")}`;
      item.append(checkbox, title, detail, path);
      list.append(item);
    });
    if (list.childElementCount) els.organizeMediaPlan.append(list);
    if (warnings.length) {
      const warningList = document.createElement("ul");
      warningList.className = "organize-warning-list";
      warnings.slice(0, 20).forEach((warning) => {
        const item = document.createElement("li");
        const reason = String(warning.reason || "");
        item.dataset.kind = reason.toLowerCase().includes("collision") ? "collision" : "warning";
        const title = document.createElement("strong");
        title.textContent = warning.name || "Élément non associé";
        const detail = document.createElement("span");
        detail.className = "organize-plan-detail";
        detail.textContent = reason;
        item.append(title, detail);
        if (warning.files) {
          const files = document.createElement("span");
          files.className = "organize-plan-detail";
          files.textContent = `Fichiers : ${warning.files}`;
          item.append(files);
        }
        const dangerous = /archive|exécutable|executable/i.test(reason);
        if (dangerous && warning.hash) {
          const classify = document.createElement("button");
          classify.type = "button";
          classify.className = "button secondary organize-classify-game";
          classify.textContent = "Classer comme jeu";
          classify.addEventListener("click", async () => {
            classify.disabled = true;
            classify.textContent = "Classification…";
            await runAdvancedAction(warning.hash, "set-category", { category: "Jeux" }, "Catégorie Jeux appliquée.");
            await openOrganizeMediaDialog(state.organizeHashes);
          });
          item.append(classify);
        }
        warningList.append(item);
      });
      els.organizeMediaPlan.append(warningList);
    }
    renderOrganizeSelection();
    els.confirmOrganizeMediaButton.disabled = entries.length + orphanMedia.length + duplicateGroups.filter((group) => group.status !== "conflict").length === 0;
    applyOrganizeFilter();
  } catch (error) {
    els.organizeMediaSummary.textContent = describeError(error);
  }
}

function applyOrganizeFilter() {
  const filter = els.organizeFilter?.value || "all";
  document.querySelectorAll("#organizeMediaPlan li[data-kind]").forEach((item) => {
    item.hidden = filter !== "all" && item.dataset.kind !== filter;
  });
}

function renderOrganizeSelection() {
  const selected = (state.organizeSelected?.size || 0) + (state.organizeOrphanSelected?.size || 0) + (state.organizeDuplicateSelected?.size || 0);
  const total = (state.organizePlanEntries?.length || 0) + (state.organizePlanOrphans?.length || 0) + (state.organizePlanDuplicates?.filter((group) => group.status !== "conflict").length || 0);
  if (els.organizeSelectionSummary) els.organizeSelectionSummary.textContent = `${selected} sélectionné${selected > 1 ? "s" : ""} sur ${total}`;
  if (els.organizeSelectAll) {
    els.organizeSelectAll.checked = total > 0 && selected === total;
    els.organizeSelectAll.indeterminate = selected > 0 && selected < total;
  }
  if (els.confirmOrganizeMediaButton) els.confirmOrganizeMediaButton.disabled = selected === 0;
}

const ORGANIZE_STAGE_ORDER = {
  preparing: 0,
  pausing: 0,
  moving: 1,
  duplicates: 1.4,
  orphans: 1.6,
  rechecking: 2,
  verification: 2.2,
  finalizing: 2.6,
  rclone: 3,
  jellyfin: 3.4,
  completed: 4,
  partial_failure: 4,
  failed: 4,
};

function organizeStageInfo(stage) {
  switch (stage) {
    case "pausing":
      return { step: 0, title: "Pause sécurisée", detail: "Mise en pause avant toute mutation." };
    case "moving":
      return { step: 1, title: "Déplacement Jellyfin", detail: "Renommage et déplacement en cours." };
    case "duplicates":
      return { step: 1, title: "Fusion des doublons", detail: "Les dossiers en doublon sélectionnés sont fusionnés." };
    case "orphans":
      return { step: 1, title: "Rangement des orphelins", detail: "Les médias sans torrent associé sont rangés." };
    case "rechecking":
      return { step: 2, title: "Revérification", detail: "qBittorrent revérifie les fichiers déplacés." };
    case "verification":
      return { step: 2, title: "Vérification", detail: "Vérification qBittorrent demandée." };
    case "finalizing":
      return { step: 2, title: "Consolidation", detail: "Journal de rangement en cours d’écriture." };
    case "rclone":
      return { step: 3, title: "Actualisation du montage", detail: "rclone rafraîchit les dossiers Films et Séries." };
    case "jellyfin":
      return { step: 3, title: "Scan Jellyfin", detail: "La bibliothèque Jellyfin est en cours d’actualisation." };
    case "completed":
      return { step: 4, title: "Rangement terminé", detail: "Toutes les étapes réelles ont été exécutées." };
    case "partial_failure":
      return { step: 4, title: "Rangement partiel", detail: "Des éléments demandent une vérification manuelle." };
    case "failed":
      return { step: 4, title: "Rangement interrompu", detail: "Le rangement n’a pas pu aboutir." };
    default:
      return { step: 0, title: "Préparation du rangement", detail: "Sélection prête — démarrage du rangement." };
  }
}

function applyOrganizeStepStates(states) {
  const steps = Array.from(els.organizeWorkflowSteps?.children || []);
  steps.forEach((node, index) => {
    const value = states[index] || "pending";
    node.dataset.state = value;
    if (value === "active") node.setAttribute("aria-current", "step");
    else node.removeAttribute("aria-current");
  });
}

function statesForOrganizeStage(stage, failedStage = "") {
  switch (stage) {
    case "moving":
    case "duplicates":
    case "orphans":
      return ["done", "active", "pending", "pending"];
    case "rechecking":
    case "verification":
    case "finalizing":
      return ["done", "done", "active", "pending"];
    case "rclone":
    case "jellyfin":
      return ["done", "done", "done", "active"];
    case "completed":
      return ["done", "done", "done", "done"];
    case "partial_failure":
      return ["done", "done", "done", "error"];
    case "failed": {
      const failedStep = failedStage === "moving" ? 1 : failedStage === "rechecking" || failedStage === "verification" ? 2 : 0;
      return Array.from({ length: 4 }, (_value, index) => index < failedStep ? "done" : index === failedStep ? "error" : "pending");
    }
    default:
      return ["active", "pending", "pending", "pending"];
  }
}

function setOrganizeRowState(row, value, label) {
  if (!row) return;
  row.dataset.state = value;
  const chip = row.querySelector(".organize-workflow-chip");
  if (chip && label && chip.textContent !== label) chip.textContent = label;
}

function createOrganizeRouteRow({ key, kind, title, meta, source, destination }) {
  const item = document.createElement("article");
  item.className = "organize-workflow-item";
  item.dataset.kind = kind;
  item.dataset.organizeKey = key;
  item.dataset.state = "pending";
  const head = document.createElement("div");
  head.className = "organize-workflow-item-head";
  const name = document.createElement("strong");
  name.textContent = title;
  const chip = document.createElement("span");
  chip.className = "organize-workflow-chip";
  chip.textContent = "En attente";
  head.append(name, chip);
  const metaLine = document.createElement("p");
  metaLine.className = "organize-workflow-item-meta";
  metaLine.textContent = meta;
  const routeLine = document.createElement("div");
  routeLine.className = "organize-workflow-route";
  const sourcePlace = document.createElement("span");
  sourcePlace.className = "organize-workflow-place source";
  sourcePlace.textContent = source || "Emplacement non renseigné";
  const track = document.createElement("span");
  track.className = "organize-workflow-track";
  track.setAttribute("aria-hidden", "true");
  const dot = document.createElement("span");
  dot.className = "organize-workflow-dot";
  track.append(dot);
  const destinationPlace = document.createElement("span");
  destinationPlace.className = "organize-workflow-place destination";
  destinationPlace.textContent = destination || "Destination Jellyfin";
  routeLine.append(sourcePlace, track, destinationPlace);
  item.append(head, metaLine, routeLine);
  return item;
}

function renderOrganizeWorkflowStart(selection) {
  state.organizeRunSelection = selection;
  state.organizeProgressItems = new Map();
  state.organizeProgressStage = "preparing";
  if (els.organizeWorkflow) {
    els.organizeWorkflow.hidden = false;
    els.organizeWorkflow.setAttribute("aria-busy", "true");
  }
  if (els.organizeSelectionToolbar) els.organizeSelectionToolbar.hidden = true;
  if (els.organizeMediaPlan) els.organizeMediaPlan.hidden = true;
  if (els.organizeMediaNote) els.organizeMediaNote.hidden = true;
  if (els.organizeWorkflowResult) {
    els.organizeWorkflowResult.hidden = true;
    els.organizeWorkflowResult.replaceChildren();
  }
  if (els.organizeWorkflowTitle) els.organizeWorkflowTitle.textContent = "Préparation du rangement";
  if (els.organizeWorkflowDetail) els.organizeWorkflowDetail.textContent = "Sélection prête — démarrage du rangement.";
  if (els.organizeWorkflowCount) els.organizeWorkflowCount.textContent = "0 / 0";
  applyOrganizeStepStates(["active", "pending", "pending", "pending"]);
  const routes = els.organizeWorkflowRoutes;
  if (routes) {
    routes.replaceChildren();
    const rows = [];
    (selection.entries || []).forEach((entry) => {
      const fileCount = Number(entry.fileCount) || 0;
      const operationCount = (entry.operations || []).length;
      rows.push({
        key: entry.hash,
        kind: "entry",
        title: entry.name,
        meta: `${entry.kind === "series" ? "Série" : "Film"} · ${fileCount} fichier${fileCount > 1 ? "s" : ""} · ${operationCount} ajustement${operationCount > 1 ? "s" : ""}`,
        source: entry.currentPath,
        destination: entry.targetPath,
      });
    });
    (selection.orphans || []).forEach((orphan) => {
      const basename = String(orphan.path || "").split("/").pop() || orphan.path;
      rows.push({
        key: `orphan:${orphan.path}`,
        kind: "orphan",
        title: basename,
        meta: "Média orphelin · aucun torrent associé",
        source: orphan.path,
        destination: "Classement Jellyfin",
      });
    });
    (selection.duplicates || []).forEach((group) => {
      const complementary = Number(group.complementaryFiles) || 0;
      rows.push({
        key: `duplicate:${group.id}`,
        kind: "duplicate",
        title: `Doublon · ${group.canonicalPath}`,
        meta: `${(group.sourcePaths || []).length} source${(group.sourcePaths || []).length > 1 ? "s" : ""} · ${complementary} fichier${complementary > 1 ? "s" : ""} complémentaire${complementary > 1 ? "s" : ""}`,
        source: (group.sourcePaths || []).join(", "),
        destination: group.canonicalPath,
      });
    });
    const fragment = document.createDocumentFragment();
    rows.slice(0, 24).forEach((row) => fragment.append(createOrganizeRouteRow(row)));
    routes.append(fragment);
    if (rows.length > 24) {
      const more = document.createElement("p");
      more.className = "organize-workflow-more";
      more.textContent = `${rows.length - 24} autre${rows.length - 24 > 1 ? "s" : ""} élément${rows.length - 24 > 1 ? "s" : ""} traité${rows.length - 24 > 1 ? "s" : ""} dans le même lot — le compteur reflète l’avancement réel.`;
      routes.append(more);
    }
  }
  els.organizeWorkflowTitle?.focus?.({ preventScroll: true });
}

function updateOrganizeRowsFromProgress(progress) {
  const items = progress?.items || {};
  const currentHash = String(progress?.hash || "");
  const stageOrder = ORGANIZE_STAGE_ORDER[progress?.stage] ?? 0;
  const entryStageLabels = {
    pausing: "Pause",
    moving: "Déplacement",
    rechecking: "Revérification",
    verification: "Vérifié",
    failed: "Échec",
  };
  els.organizeWorkflowRoutes?.querySelectorAll(".organize-workflow-item").forEach((row) => {
    const key = row.dataset.organizeKey || "";
    if (row.dataset.kind === "entry") {
      const item = items[key];
      if (item) {
        const value = item.stage === "failed" ? "error" : item.stage === "verification" ? "done" : "active";
        setOrganizeRowState(row, value, entryStageLabels[item.stage] || "En cours");
      } else if (currentHash && currentHash === key) {
        setOrganizeRowState(row, "active", "En cours");
      }
      return;
    }
    if (progress?.stage === "failed") return;
    const ownOrder = row.dataset.kind === "duplicate" ? ORGANIZE_STAGE_ORDER.duplicates : ORGANIZE_STAGE_ORDER.orphans;
    if (stageOrder > ownOrder) setOrganizeRowState(row, "done", "Traité");
    else if (stageOrder === ownOrder) setOrganizeRowState(row, "active", row.dataset.kind === "duplicate" ? "Fusion" : "Rangement");
  });
}

function renderOrganizeProgressRun(run) {
  const progress = run?.progress || {};
  const stage = String(progress.stage || run?.stage || "preparing");
  state.organizeProgressStage = stage;
  state.organizeProgressFailedStage = String(progress.failedStage || "");
  if (progress.items && typeof progress.items === "object") {
    state.organizeProgressItems = new Map(Object.entries(progress.items));
  }
  const info = organizeStageInfo(stage);
  const message = String(progress.message || "").trim() || info.detail;
  if (els.organizeWorkflowTitle && els.organizeWorkflowTitle.textContent !== info.title) {
    els.organizeWorkflowTitle.textContent = info.title;
  }
  if (els.organizeWorkflowDetail && els.organizeWorkflowDetail.textContent !== message) {
    els.organizeWorkflowDetail.textContent = message;
  }
  if (els.organizeWorkflowCount) {
    const total = Number(progress.total) || (state.organizeRunSelection?.entries || []).length;
    const processed = Number(progress.processed) || 0;
    const label = total ? `${Math.min(processed, total)} / ${total} torrent${total > 1 ? "s" : ""}` : "Étape en cours";
    if (els.organizeWorkflowCount.textContent !== label) els.organizeWorkflowCount.textContent = label;
  }
  applyOrganizeStepStates(statesForOrganizeStage(stage, state.organizeProgressFailedStage));
  updateOrganizeRowsFromProgress(progress);
  const done = stage === "completed" || stage === "partial_failure" || stage === "failed";
  els.organizeWorkflow?.setAttribute("aria-busy", done ? "false" : "true");
}

function renderOrganizeProgressJob(job) {
  const data = job?.data && typeof job.data === "object" ? job.data : {};
  const total = Number(job?.total);
  const progress = Number(job?.progress);
  state.organizeProgressStage = String(data.stage || state.organizeProgressStage || "preparing");
  if (data.hash) updateOrganizeRowsFromProgress({ stage: state.organizeProgressStage, hash: data.hash });
  if (els.organizeWorkflowTitle && job?.message) els.organizeWorkflowTitle.textContent = job.message;
  if (els.organizeWorkflowDetail) {
    els.organizeWorkflowDetail.textContent = total > 0 && Number.isFinite(progress)
      ? `${Math.min(progress, total)} / ${total} étape(s) terminée(s).`
      : job?.message || "Tâche en cours.";
  }
  if (total > 0 && els.organizeWorkflowCount) els.organizeWorkflowCount.textContent = `${Math.min(progress || 0, total)} / ${total}`;
  els.refreshStatus.textContent = jobProgressLabel(job);
}

function renderOrganizeWorkflowResult(payload) {
  const result = payload?.result || {};
  const refresh = payload?.refresh || {};
  const organized = Number(result.organized) || 0;
  const failed = Number(result.failed) || 0;
  const merged = Number(result.duplicatesMerged) || 0;
  const orphans = Number(result.orphansOrganized) || 0;
  const orphanResults = Array.isArray(result.orphanResults) ? result.orphanResults : [];
  const duplicateResults = Array.isArray(result.duplicateGroups) ? result.duplicateGroups : [];
  const failedOrphans = orphanResults.filter((item) => !item.success).length;
  const failedDuplicates = duplicateResults.filter((item) => !item.success).length;
  const hasFailure = failed > 0 || orphanResults.some((item) => !item.success) || duplicateResults.some((item) => !item.success);
  const jellyfinFailed = refresh.jellyfin === "failed" || refresh.rclone === "failed";
  const jellyfinState = jellyfinFailed ? "error" : refresh.jellyfin === "requested" ? "done" : "pending";
  applyOrganizeStepStates(["done", "done", hasFailure ? "error" : "done", jellyfinState]);
  if (els.organizeWorkflowTitle) els.organizeWorkflowTitle.textContent = hasFailure ? "Rangement partiel" : "Rangement terminé";
  const summary = [
    `${organized} torrent${organized > 1 ? "s" : ""} rangé${organized > 1 ? "s" : ""}`,
    failed ? `${failed} échec${failed > 1 ? "s" : ""}` : "",
    merged ? `${merged} fusion${merged > 1 ? "s" : ""} de doublons` : "",
    orphans ? `${orphans} média${orphans > 1 ? "s" : ""} orphelin${orphans > 1 ? "s" : ""} rangé${orphans > 1 ? "s" : ""}` : "",
  ].filter(Boolean).join(" · ");
  if (els.organizeWorkflowDetail) els.organizeWorkflowDetail.textContent = summary || "Aucune mutation nécessaire.";
  const entryTotal = (state.organizeRunSelection?.entries || []).length;
  if (els.organizeWorkflowCount) {
    els.organizeWorkflowCount.textContent = entryTotal ? `${Math.min(organized + failed, entryTotal)} / ${entryTotal} torrent${entryTotal > 1 ? "s" : ""}` : "Terminé";
  }
  els.organizeWorkflowRoutes?.querySelectorAll(".organize-workflow-item").forEach((row) => {
    const key = row.dataset.organizeKey || "";
    if (row.dataset.kind === "entry") {
      const item = (result.results || []).find((entry) => String(entry.hash) === key);
      if (item) setOrganizeRowState(row, item.success ? "done" : "error", item.success ? "Vérifié" : "Échec");
    } else if (row.dataset.kind === "orphan") {
      const item = orphanResults.find((entry) => `orphan:${entry.path}` === key);
      if (item) setOrganizeRowState(row, item.success ? "done" : "error", item.success ? "Rangé" : "Échec");
    } else if (row.dataset.kind === "duplicate") {
      const item = duplicateResults.find((entry) => `duplicate:${entry.id}` === key);
      if (item) setOrganizeRowState(row, item.success ? "done" : "error", item.success ? "Fusionné" : "Échec");
    }
  });
  if (els.organizeWorkflowResult) {
    els.organizeWorkflowResult.replaceChildren();
    const lines = [];
    if (organized) lines.push(`${organized} torrent${organized > 1 ? "s" : ""} rangé${organized > 1 ? "s" : ""} et revérifié${organized > 1 ? "s" : ""} par qBittorrent.`);
    if (failed) {
      const names = (result.results || []).filter((item) => !item.success).map((item) => item.name).filter(Boolean).slice(0, 3);
      lines.push(`${failed} torrent${failed > 1 ? "s" : ""} en échec${names.length ? ` : ${names.join(", ")}` : ""}.`);
    }
    if (merged) lines.push(`${merged} fusion${merged > 1 ? "s" : ""} de doublons appliquée${merged > 1 ? "s" : ""}, revérification demandée.`);
    if (orphans) lines.push(`${orphans} média${orphans > 1 ? "s" : ""} orphelin${orphans > 1 ? "s" : ""} rangé${orphans > 1 ? "s" : ""}.`);
    if (failedOrphans) lines.push(`${failedOrphans} média${failedOrphans > 1 ? "s" : ""} orphelin${failedOrphans > 1 ? "s" : ""} non rangé${failedOrphans > 1 ? "s" : ""}.`);
    if (failedDuplicates) lines.push(`${failedDuplicates} fusion${failedDuplicates > 1 ? "s" : ""} de doublons en échec.`);
    if (refresh.rclone === "requested") lines.push("Montage rclone actualisé.");
    else if (refresh.rclone === "failed") lines.push(`Rafraîchissement rclone en échec : ${refresh.rcloneMessage || "réessayer plus tard"}.`);
    if (refresh.jellyfin === "requested") lines.push("Scan Jellyfin demandé.");
    else if (refresh.jellyfin === "failed") lines.push(`Scan Jellyfin en échec : ${refresh.jellyfinMessage || "vérifier la clé API"}.`);
    lines.push("Les torrents restent en pause ; la reprise est manuelle après vérification à 100 %.");
    lines.forEach((line) => {
      const paragraph = document.createElement("p");
      paragraph.textContent = line;
      els.organizeWorkflowResult.append(paragraph);
    });
    els.organizeWorkflowResult.hidden = false;
  }
  els.organizeWorkflow?.setAttribute("aria-busy", "false");
}

function renderOrganizeWorkflowError(error) {
  applyOrganizeStepStates(statesForOrganizeStage("failed", state.organizeProgressFailedStage || state.organizeProgressStage));
  const activeRow = els.organizeWorkflowRoutes?.querySelector('.organize-workflow-item[data-state="active"]');
  setOrganizeRowState(activeRow, "error", "Échec");
  if (els.organizeWorkflowTitle) els.organizeWorkflowTitle.textContent = "Rangement interrompu";
  if (els.organizeWorkflowDetail) els.organizeWorkflowDetail.textContent = describeError(error);
  if (els.organizeWorkflowResult) {
    els.organizeWorkflowResult.replaceChildren();
    const paragraph = document.createElement("p");
    paragraph.textContent = describeError(error);
    els.organizeWorkflowResult.append(paragraph);
    els.organizeWorkflowResult.hidden = false;
  }
  els.organizeWorkflow?.setAttribute("aria-busy", "false");
}

function resetOrganizeWorkflow() {
  state.organizeRunning = false;
  state.organizeFinished = false;
  state.organizeRunSelection = null;
  state.organizeProgressItems = new Map();
  state.organizeProgressStage = "preparing";
  state.organizeProgressFailedStage = "";
  if (els.organizeWorkflow) {
    els.organizeWorkflow.hidden = true;
    els.organizeWorkflow.setAttribute("aria-busy", "false");
  }
  if (els.organizeWorkflowRoutes) els.organizeWorkflowRoutes.replaceChildren();
  if (els.organizeWorkflowResult) {
    els.organizeWorkflowResult.hidden = true;
    els.organizeWorkflowResult.replaceChildren();
  }
  if (els.organizeWorkflowCount) els.organizeWorkflowCount.textContent = "0 / 0";
  if (els.organizeWorkflowTitle) els.organizeWorkflowTitle.textContent = "Préparation du rangement";
  if (els.organizeWorkflowDetail) els.organizeWorkflowDetail.textContent = "Sélection prête.";
  applyOrganizeStepStates(["pending", "pending", "pending", "pending"]);
  if (els.organizeSelectionToolbar) els.organizeSelectionToolbar.hidden = false;
  if (els.organizeMediaPlan) els.organizeMediaPlan.hidden = false;
  if (els.organizeMediaNote) els.organizeMediaNote.hidden = false;
  if (els.cancelOrganizeMediaButton) {
    els.cancelOrganizeMediaButton.disabled = false;
    els.cancelOrganizeMediaButton.textContent = "Annuler";
  }
  if (els.confirmOrganizeMediaButton) {
    els.confirmOrganizeMediaButton.hidden = false;
    els.confirmOrganizeMediaButton.disabled = false;
    els.confirmOrganizeMediaButton.textContent = "Ranger et revérifier";
  }
}

function cancelOrganizeMedia() {
  if (state.organizeRunning) {
    els.organizeMediaDialog?.close();
    showToast("Le rangement continue en arrière-plan.");
    return;
  }
  els.organizeMediaDialog?.close();
}

async function confirmOrganizeMedia() {
  if (state.organizeRunning) return;
  const hashes = [...(state.organizeSelected || new Set())];
  const orphanPaths = [...(state.organizeOrphanSelected || new Set())];
  const duplicateGroupIds = [...(state.organizeDuplicateSelected || new Set())];
  const selection = {
    entries: (state.organizePlanEntries || []).filter((entry) => state.organizeSelected.has(entry.hash)),
    orphans: (state.organizePlanOrphans || []).filter((orphan) => state.organizeOrphanSelected.has(orphan.path)),
    duplicates: (state.organizePlanDuplicates || []).filter((group) => state.organizeDuplicateSelected.has(group.id)),
  };
  state.organizeRunning = true;
  state.organizeFinished = false;
  els.confirmOrganizeMediaButton.disabled = true;
  els.confirmOrganizeMediaButton.textContent = "Rangement…";
  if (els.cancelOrganizeMediaButton) els.cancelOrganizeMediaButton.disabled = true;
  els.organizeMediaMessage.textContent = "";
  renderOrganizeWorkflowStart(selection);
  if (els.cancelOrganizeMediaButton) {
    els.cancelOrganizeMediaButton.disabled = false;
    els.cancelOrganizeMediaButton.textContent = "Continuer en arrière-plan";
  }
  try {
    state.actionRevision += 1;
    const submitted = await submitJob("library-apply", {
      hashes,
      orphanPaths,
      duplicateGroupIds,
      runId: state.organizeRunId || null,
    });
    els.organizeMediaDialog.close();
    showToast("Rangement lancé. La progression reste visible dans la barre d’état.");
    const job = await waitForJob(submitted.id, (value) => renderOrganizeProgressJob(value));
    const payload = job.result || {};
    const result = payload.result || {};
    const refresh = payload.refresh || {};
    const parts = [`${result.organized || 0} rangé${result.organized > 1 ? "s" : ""}`];
    if (result.failed) parts.push(`${result.failed} échec${result.failed > 1 ? "s" : ""}`);
    if (result.duplicatesMerged) parts.push(`${result.duplicatesMerged} fusion${result.duplicatesMerged > 1 ? "s" : ""}`);
    if (refresh.rclone === "failed") parts.push("rafraîchissement rclone en échec");
    if (refresh.jellyfin === "failed") parts.push("scan Jellyfin en échec");
    renderOrganizeWorkflowResult(payload);
    state.organizeRunning = false;
    state.organizeFinished = true;
    showToast(`Rangement : ${parts.join(", ")}. Les torrents restent en pause ; reprise manuelle après vérification à 100 %.`);
    if (els.cancelOrganizeMediaButton) {
      els.cancelOrganizeMediaButton.disabled = false;
      els.cancelOrganizeMediaButton.textContent = "Fermer";
    }
    if (els.confirmOrganizeMediaButton) els.confirmOrganizeMediaButton.hidden = true;
    await loadTorrents({ silent: true, force: true });
  } catch (error) {
    state.organizeRunning = false;
    renderOrganizeWorkflowError(error);
    els.organizeMediaMessage.textContent = describeError(error);
    showToast(describeError(error));
    resumeLiveAfterAction();
    if (els.confirmOrganizeMediaButton) {
      els.confirmOrganizeMediaButton.hidden = false;
      els.confirmOrganizeMediaButton.disabled = false;
      els.confirmOrganizeMediaButton.textContent = "Réessayer";
    }
    if (els.cancelOrganizeMediaButton) {
      els.cancelOrganizeMediaButton.disabled = false;
      els.cancelOrganizeMediaButton.textContent = "Annuler";
    }
    if (els.organizeSelectionToolbar) els.organizeSelectionToolbar.hidden = false;
    if (els.organizeMediaPlan) els.organizeMediaPlan.hidden = false;
    if (els.organizeMediaNote) els.organizeMediaNote.hidden = false;
  }
}

function configureLinks() {
  window.DashboardNavigation?.configure(state, state.activeView === "home" ? "home" : "torrent");
  if (els.torrentsNavLink) els.torrentsNavLink.href = `${route("/")}?view=torrents`;
}

async function submitMagnets(event) {
  event.preventDefault();
  els.magnetMessage.textContent = "";
  const magnets = els.magnetInput.value.splitlines?.() || els.magnetInput.value.split(/\r?\n/);
  const valid = magnets.map((item) => item.trim()).filter(Boolean);
  if (!valid.length) {
    els.magnetMessage.textContent = "Ajoutez au moins un lien magnet.";
    els.magnetInput.focus();
    return;
  }
  els.addButton.disabled = true;
  els.addButton.textContent = "Ajout…";
  state.actionRevision += 1;
  beginGlobalAction();
  try {
    const payload = await api(route("/api/torrents/add"), {
      method: "POST",
      body: JSON.stringify({
        magnets: valid,
        category: els.categoryInput.value.trim(),
        tags: els.tagsInput.value.trim(),
        paused: els.pausedInput.checked,
        addTr4kerTracker: Boolean(els.tr4kerTrackerInput?.checked),
      }),
    });
    const rejected = Array.isArray(payload.rejected) ? payload.rejected : [];
    state.prefs.lastCategory = els.categoryInput.value.trim();
    state.prefs.lastTags = els.tagsInput.value.trim();
    savePrefs();
    els.magnetMessage.textContent = `${payload.accepted || 0} accepté${payload.accepted > 1 ? "s" : ""}, ${rejected.length} refusé${rejected.length > 1 ? "s" : ""}.`;
    if (payload.accepted) {
      els.magnetInput.value = "";
      showToast(payload.tr4kerTrackerApplied ? "Magnet envoyé à qBittorrent avec l'annonce TR4KER." : "Magnet envoyé à qBittorrent.");
      await loadTorrents({ silent: true, force: true });
      loadTrackerIndex();
    }
  } catch (error) {
    els.magnetMessage.textContent = describeError(error);
    els.magnetInput.focus();
  } finally {
    endGlobalAction();
    els.addButton.disabled = false;
    els.addButton.textContent = "Ajouter";
  }
}

function restartRefreshTimer() {
  window.clearInterval(state.refreshTimer);
  state.refreshTimer = null;
  if (!state.prefs.autoRefresh) {
    if (state.liveSubscription) stopLive();
    return;
  }
  if (state.liveSubscription) return;
  state.refreshTimer = window.setInterval(() => {
    loadTorrents({ silent: true });
  }, Number(state.prefs.refreshIntervalMs) || 9000);
}

function updatePreference(key, value) {
  if (["search", "status", "category", "tag", "tracker", "sort", "direction"].includes(key)) {
    resetTorrentWindow();
  }
  state.prefs[key] = value;
  savePrefs();
  updateUrl();
  render();
}

function scheduleSearchPreference(value) {
  window.clearTimeout(state.searchTimer);
  state.searchTimer = window.setTimeout(() => {
    state.searchTimer = null;
    if (state.prefs.search === value) return;
    updatePreference("search", value);
  }, SEARCH_DEBOUNCE_MS);
}

function resetFilters() {
  window.clearTimeout(state.searchTimer);
  state.searchTimer = null;
  state.prefs = { ...state.prefs, search: "", status: "all", category: "all", tag: "all", tracker: "all", sort: "default", direction: "asc" };
  resetTorrentWindow();
  savePrefs();
  updateUrl();
  render();
}

function openAddPanel() {
  const addPanel = document.querySelector("#addPanel");
  if (addPanel) addPanel.open = true;
  state.activeView = "torrents";
  setView("torrents");
  els.magnetInput.focus();
  render();
}

function bindEvents() {
  els.refreshButton.addEventListener("click", () => loadTorrents({ force: true }));
  els.showPreviousRows?.addEventListener("click", () => {
    state.renderOffset = Math.max(0, state.renderOffset - MAX_RENDERED_TORRENTS);
    render();
  });
  els.loadMoreRows?.addEventListener("click", () => {
    state.renderOffset += MAX_RENDERED_TORRENTS;
    render();
  });
  els.openAddPanelButton.addEventListener("click", openAddPanel);
  els.addTorrentButton?.addEventListener("click", openAddPanel);
  els.retryButton.addEventListener("click", () => loadTorrents({ force: true }));
  els.searchInput.addEventListener("input", (event) => scheduleSearchPreference(event.currentTarget?.value ?? els.searchInput.value));
  els.statusFilter.addEventListener("change", () => updatePreference("status", els.statusFilter.value));
  els.categoryFilter.addEventListener("change", () => updatePreference("category", els.categoryFilter.value));
  els.tagFilter.addEventListener("change", () => updatePreference("tag", els.tagFilter.value));
  els.trackerFilter.addEventListener("change", () => updatePreference("tracker", els.trackerFilter.value));
  els.sortSelect.addEventListener("change", () => updatePreference("sort", els.sortSelect.value));
  els.sortDirectionSelect?.addEventListener("change", () => updatePreference("direction", els.sortDirectionSelect.value));
  els.resetFilters.addEventListener("click", resetFilters);
  els.clearActiveFilters.addEventListener("click", resetFilters);
  els.autoRefreshToggle.addEventListener("change", () => {
    state.prefs.autoRefresh = els.autoRefreshToggle.checked;
    savePrefs();
    if (state.prefs.autoRefresh) startLive();
    else stopLive();
    restartRefreshTimer();
    renderControls();
  });
  els.refreshInterval.addEventListener("change", () => {
    state.prefs.refreshIntervalMs = Number(els.refreshInterval.value);
    savePrefs();
    restartRefreshTimer();
  });
  document.querySelectorAll(".sort-head").forEach((head) => head.addEventListener("click", () => setSort(head.dataset.sort)));
  els.quickFilters.addEventListener("click", (event) => {
    const clicked = event.target.closest("[data-quick-filter]");
    if (!clicked) return;
    setStatusFromQuickFilter(clicked.dataset.quickFilter);
  });
  els.summaryGrid.addEventListener("click", (event) => {
    const clicked = event.target.closest("[data-filter]");
    if (!clicked) return;
    state.activeView = "torrents";
    setView("torrents");
    setStatusFromQuickFilter(clicked.dataset.filter);
  });
  els.selectVisible.addEventListener("change", () => {
    const visible = renderedTorrents();
    if (els.selectVisible.checked) visible.forEach((torrent) => state.selected.add(torrent.hash));
    else visible.forEach((torrent) => state.selected.delete(torrent.hash));
    render();
  });
  els.bulkPause.addEventListener("click", () => runTorrentAction([...state.selected], "pause"));
  els.bulkResume.addEventListener("click", () => runTorrentAction([...state.selected], "resume"));
  els.bulkForceShare.addEventListener("click", () => {
    const selectedTorrents = state.torrents.filter((torrent) => state.selected.has(torrent.hash));
    const eligible = selectedTorrents.filter((torrent) => isComplete(torrent) || torrent.state === "forcedUP");
    if (!eligible.length) {
      showToast("Sélectionnez au moins un torrent terminé pour utiliser le partage forcé.");
      return;
    }
    const disableForcedShare = eligible.every((torrent) => torrent.state === "forcedUP");
    runTorrentAction(eligible.map((torrent) => torrent.hash), "force-start", { enabled: !disableForcedShare });
  });
  els.bulkAddTr4kerTracker.addEventListener("click", () => addConfiguredTracker("/api/torrents/add-tr4ker-tracker", "Tracker tr4ker configuré"));
  els.bulkAddTracker.addEventListener("click", openAddTrackerDialog);
  els.bulkDelete.addEventListener("click", (event) => {
    const selectedTorrents = state.torrents.filter((torrent) => state.selected.has(torrent.hash));
    openDeleteDialog(selectedTorrents, event.currentTarget);
  });
  els.confirmAddTrackerButton.addEventListener("click", confirmAddTracker);
  els.cancelAddTrackerButton.addEventListener("click", cancelAddTracker);
  els.addTrackerDialog.addEventListener("close", () => state.lastFocus?.focus?.());
  els.relinkMissingButton.addEventListener("click", () => openRelinkDialog());
  document.querySelectorAll('input[name="relinkMode"]').forEach((input) => {
    input.addEventListener("change", () => setRelinkMode(input.value));
  });
  els.confirmRelinkButton.addEventListener("click", confirmRelink);
  els.cancelRelinkButton.addEventListener("click", cancelRelink);
  els.relinkDialog.addEventListener("close", () => state.lastFocus?.focus?.());
  document.querySelector("#relinkForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    confirmRelink();
  });
  els.organizeMediaButton?.addEventListener("click", (event) => openOrganizeMediaDialog([], event.currentTarget));
  els.confirmOrganizeMediaButton?.addEventListener("click", confirmOrganizeMedia);
  els.organizeSelectAll?.addEventListener("change", () => {
    state.organizeSelected = new Set(els.organizeSelectAll.checked ? (state.organizePlanEntries || []).map((entry) => entry.hash) : []);
    state.organizeOrphanSelected = new Set(els.organizeSelectAll.checked ? (state.organizePlanOrphans || []).map((item) => item.path) : []);
    state.organizeDuplicateSelected = new Set(els.organizeSelectAll.checked ? (state.organizePlanDuplicates || []).filter((group) => group.status !== "conflict").map((group) => group.id) : []);
    document.querySelectorAll("#organizeMediaPlan input[type=checkbox]").forEach((checkbox) => {
      checkbox.checked = els.organizeSelectAll.checked && !checkbox.disabled;
    });
    renderOrganizeSelection();
  });
  els.organizeFilter?.addEventListener("change", applyOrganizeFilter);
  els.cancelOrganizeMediaButton?.addEventListener("click", cancelOrganizeMedia);
  els.organizeMediaDialog?.addEventListener("cancel", (event) => {
    if (state.organizeRunning) event.preventDefault();
  });
  els.organizeMediaDialog?.addEventListener("close", () => {
    if (!state.organizeRunning) resetOrganizeWorkflow();
    state.lastFocus?.focus?.();
  });
  document.querySelector("#organizeMediaForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    confirmOrganizeMedia();
  });
  els.addTrackerUrlInput.addEventListener("keydown", (event) => {
    if (event.key === "Enter") {
      event.preventDefault();
      confirmAddTracker();
    }
  });
  document.querySelector("#addTrackerForm")?.addEventListener("submit", (event) => {
    event.preventDefault();
    confirmAddTracker();
  });
  els.addForm.addEventListener("submit", submitMagnets);
  els.deleteForm.addEventListener("change", updateDeleteConfirm);
  els.confirmText.addEventListener("input", updateDeleteConfirm);
  els.cancelDeleteButton.addEventListener("click", () => {
    state.pendingDelete = null;
    els.deleteDialog.close();
  });
  els.confirmDeleteButton.addEventListener("click", confirmDelete);
  els.deleteForm.addEventListener("submit", (event) => {
    event.preventDefault();
    confirmDelete();
  });
  els.deleteDialog.addEventListener("close", () => state.lastFocus?.focus?.());
  els.detailDialog.addEventListener("close", () => {
    state.detailHash = "";
    state.lastFocus?.focus?.();
  });
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) loadTorrents({ silent: true, force: true });
  });
  window.addEventListener?.("popstate", () => {
    window.clearTimeout(state.searchTimer);
    state.searchTimer = null;
    applyUrlState();
    render();
  });
}

if (els.densityToggle) {
  els.densityToggle.addEventListener("click", () => {
    const panel = document.querySelector(".torrents-panel");
    const compact = panel ? !panel.classList.contains("compact") : true;
    if (panel) {
      if (compact) panel.classList.add("compact");
      else panel.classList.remove("compact");
    }
    els.densityToggle.setAttribute("aria-pressed", String(compact));
    els.densityToggle.textContent = compact ? "Vue normale" : "Vue compacte";
    state.prefs.density = compact ? "compact" : "normal";
    savePrefs();
  });
}

// Barre de filtres sticky
(function wireStickyFilters() {
  const filters = document.querySelector(".torrents-panel .filters");
  if (!filters || !("IntersectionObserver" in window)) return;
  const sentinel = document.createElement("div");
  sentinel.setAttribute("aria-hidden", "true");
  filters.parentNode.insertBefore(sentinel, filters);
  new IntersectionObserver(([entry]) => {
    filters.classList.toggle("is-stuck", !entry.isIntersecting);
  }, { rootMargin: "-56px 0px 0px 0px" }).observe(sentinel);
})();

async function init() {
  configureLinks();
  bindEvents();
  applyUrlState();
  setView(state.activeView, { push: false });
  renderControls();
  restartRefreshTimer();
  try {
    await refreshSession();
    startLive();
    await loadTorrents({ force: true });
    loadTrackerIndex();
    const url = currentUrl();
    if (url.searchParams.get("add") === "1") openAddPanel();
    if (url.searchParams.get("refresh") === "1") await loadTorrents({ force: true });
  } catch (error) {
    try {
      await loadDashboard();
      render();
    } catch {}
    showError(error);
    els.refreshStatus.textContent = "Erreur";
  }
}

init();

globalThis.__testApi = { formatBytes, formatSpeed, formatRatio, formatEta, stateMeta, filteredTorrents, formatFreshness, showUndoToast, state };
